L5_1 = {}
L5_1.m_CutScenKey_Talk = "EP5_ACT1_PROLOGUE@5#Talk"
L5_1.m_CutScenProcessKey = 5
L5_1.m_CutScenID = 159
L5_1.m_CutScenStrID = "EP5_ACT1_PROLOGUE"
L5_1.m_bWaitClick = true
L5_1.m_fWaitTime = 0
L5_1.m_CharStrID = "IAN_EXTRA_NULL_NULL"
L5_1.m_Talk_KOREA = "셀카는 그다지 찍어본 적이 없어서 잘 나오고 있는 건지 모르겠군."
L5_1.m_fTalkTime = 0.03
L5_1.m_Talk_JPN = "自撮りの経験がないから、ちゃんと撮れているかどうかわからんな。"
L5_1.m_Talk_ENG = "I've never been much of a selfie person. I have no idea what I'm doing."
L5_1.m_Talk_TWN = "我沒有很常自拍，所以不知道拍得好不好。"
L5_1.m_Talk_THA = "ผมไม่ใช่คนชอบเซลฟี่เท่าไหร่ ไม่รู้เลยว่านี่กำลังทำอะไรอยู่"
L5_1.m_Talk_VTN = "Tôi chưa bao giờ là người thích selfie. Tôi không biết tôi đang làm gì nữa."
L5_1.m_Talk_SCN = "我不经常自拍，不知道能不能拍好。"
L5_1.m_Talk_DEU = "Ich war noch nie ein großer Fan von Selfies. Ich habe keine Ahnung, was ich hier tue …"
L5_1.m_Talk_FRA = "Je n'ai jamais été très porté sur les selfies. Je n'ai aucune idée de ce que je fais."
L6_1 = {}
L6_1.m_CutScenKey_Talk = "EP5_ACT1_PROLOGUE@6#Talk"
L6_1.m_CutScenProcessKey = 6
L6_1.m_CutScenID = 159
L6_1.m_CutScenStrID = "EP5_ACT1_PROLOGUE"
L6_1.m_bWaitClick = true
