L6_1.m_fFadeTime = 1
L6_1.m_CharStrID = "IAN_EXTRA_NULL_NULL"
L6_1.m_Talk_KOREA = "하지만 뭐, 아이돌 오디션 보는 것도 아닌데 너무 신경 쓸 필요는 없겠지?"
L6_1.m_fTalkTime = 0.03
L6_1.m_Talk_JPN = "まあ、アイドルオーディションじゃあるまいし、そこまで気にすることないか。"
L6_1.m_Talk_ENG = "Well, It's not like I'm applying for a talent show. Who cares?"
L6_1.m_Talk_TWN = "但又不是偶像試鏡，應該沒什麼問題吧？"
L6_1.m_Talk_THA = "แต่ก็ใช่ว่าผมกำลังสมัครรายการประกวดนี่นะ ใครจะไปสนล่ะ?"
L6_1.m_Talk_VTN = "Chà, tôi không phải đăng ký tham gia một chương trình tài năng. Ai quan tâm cơ chứ?"
L6_1.m_Talk_SCN = "但又不是偶像选秀，应该没什么问题吧？"
L6_1.m_Talk_DEU = "Na ja, ich bewerbe mich ja nicht für eine Talentshow. Also, wen kümmerts?"
L6_1.m_Talk_FRA = "Enfin, c'est pas comme si j'étais en train de passer une audition."
L7_1 = {}
