L7_1.m_Talk_KOREA = "어차피 내용이 중요한 거니까...... 대충 보라고, 시청자 여러분."
L7_1.m_fTalkTime = 0.03
L7_1.m_Talk_JPN = "何せ中身のほうが大事だからな……細かいことは気にしないでくれ、ご覧の皆さん。"
L7_1.m_Talk_ENG = "It's the content that matters. So suck it up if this turns out to be an eyesore."
L7_1.m_Talk_TWN = "反正重要的是內容…… 觀眾朋友們就隨便看看吧。"
L7_1.m_Talk_THA = "สิ่งที่สำคัญคือเนื้อหา ดังนั้นถ้าถ่ายออกมาไม่ดีก็ยอมรับมันไปซะ"
L7_1.m_Talk_VTN = "Nội dung rất quan trọng. Vì vậy, hãy nuốt nó vào trong bụng đi nếu điều này trở nên chướng mắt."
L7_1.m_Talk_SCN = "重要的是内容……各位将就着看吧。"
L7_1.m_Talk_DEU = "Auf den Inhalt kommt es an – also Pech gehabt, wenn es schlimm aussieht."
L7_1.m_Talk_FRA = "L'important, c'est le contenu. Tant pis si ça ne ressemble à rien."
