L20_1.m_Pos = "C"
L20_1.m_Talk_KOREA = "하지만 그게 정식 조사내용인 걸 어쩌겠어?"
L20_1.m_fTalkTime = 0.03
L20_1.m_Talk_JPN = "けど、公式調査の結果がそうなんだからどうしようもねえ。"
L20_1.m_Talk_ENG = "But that's the official result of the investigation."
L20_1.m_Talk_TWN = "但那就是調查結果，又有什麼辦法呢？"
L20_1.m_Talk_THA = "แต่นั่นคือผลการสืบสวนอย่างเป็นทางการเลยนะ"
L20_1.m_Talk_VTN = "Nhưng đó là kết quả chính thức của cuộc điều tra."
L20_1.m_Talk_SCN = "但调查结果就是这样，又有什么办法呢？"
L20_1.m_Talk_DEU = "Aber das ist das offizielle Ergebnis der Ermittlungen."
L20_1.m_Talk_FRA = "Mais c'est la conclusion officielle de l'enquête."
L21_1 = {}
L21_1.m_CutScenKey_Talk = "EP5_ACT1_PROLOGUE@21#Talk"
L21_1.m_CutScenProcessKey = 21
L21_1.m_CutScenID = 159
L21_1.m_CutScenStrID = "EP5_ACT1_PROLOGUE"
L21_1.m_bWaitClick = true
L21_1.m_fWaitTime = 0
L21_1.m_CharStrID = "JOHN_MASON_NULL_NULL"
L21_1.m_Pos = "C"
L21_1.m_Talk_KOREA = "나도 몇 번이나 이의신청을 했지만 담당 조사관들은 들은 체도 하지 않더군."
L21_1.m_fTalkTime = 0.03
L21_1.m_Talk_JPN = "俺も何度も異議申し立てをしたが、担当調査官らはまったく聞く耳を持たなかったんだ。"
L21_1.m_Talk_ENG = "I filed an objection several times, but the investigators didn't even pretend to listen."
L21_1.m_Talk_TWN = "雖然我對這件事提出了好幾次異議，但負責調查的官員們卻充耳不聞。"
L21_1.m_Talk_THA = "ผมส่งคำร้องคัดค้านไปหลายครั้ง แต่เจ้าหน้าที่สืบสวนก็ไม่แม้แต่จะแกล้งทำเป็นฟังด้วยซ้ำ"
L21_1.m_Talk_VTN = "Tôi đã đệ đơn phản đối nhiều lần, nhưng các điều tra viên thậm chí không thèm giả bộ lắng nghe."
L21_1.m_Talk_SCN = "我对此提出过异议，但是负责调查的官员们却充耳不闻。"
L21_1.m_Talk_DEU = "Ich habe mehrmals Einspruch erhoben – aber die Ermittler gaben nicht einmal vor, mir zuzuhören."
L21_1.m_Talk_FRA = "J'ai déposé un recours plusieurs fois, mais les enquêteurs n'ont même pas fait semblant de m'écouter."
