L27_1 = {}
L27_1.m_CutScenKey_Talk = "EP5_ACT1_PROLOGUE@27#Talk"
L27_1.m_CutScenProcessKey = 27
L27_1.m_CutScenID = 159
L27_1.m_CutScenStrID = "EP5_ACT1_PROLOGUE"
L27_1.m_bWaitClick = true
L27_1.m_fWaitTime = 0
L27_1.m_Face = "UNIT_DESPAIR"
L27_1.m_CharStrID = "JOHN_MASON_NULL_NULL"
L27_1.m_Pos = "C"
L27_1.m_Talk_KOREA = "내 입으로 말하긴 뭐하지만, 형은 꽤 괜찮은 인간이었어."
L27_1.m_fTalkTime = 0.03
L27_1.m_Talk_JPN = "俺が言うのも何なんだが、兄貴は結構いい奴でな。"
L27_1.m_Talk_ENG = "Though I say it myself, Ian was a decent human being."
L27_1.m_Talk_TWN = "雖然我自己說有點那個啦，但我哥是個很好的人。"
L27_1.m_Talk_THA = "ผมบอกได้เลยนะ เอียนเป็นมนุษย์ที่ดีจริงๆ"
L27_1.m_Talk_VTN = "Mặc dù chính tôi đã nói vậy, Ian là một người tử tế."
L27_1.m_Talk_SCN = "不是因为是我哥哥才夸他，他曾经真的是个很不错的人。"
L27_1.m_Talk_DEU = "Ich mag voreingenommen sein, aber Ian war ein anständiger Mensch."
L27_1.m_Talk_FRA = "Je suis le premier à le dire, Ian était un homme bien."
L28_1 = {}
L28_1.m_CutScenKey_Talk = "EP5_ACT1_PROLOGUE@28#Talk"
L28_1.m_CutScenProcessKey = 28
L28_1.m_CutScenID = 159
L28_1.m_CutScenStrID = "EP5_ACT1_PROLOGUE"
L28_1.m_bWaitClick = true
L28_1.m_fWaitTime = 0
L28_1.m_CharStrID = "JOHN_MASON_NULL_NULL"
L28_1.m_Pos = "C"
L28_1.m_Talk_KOREA = "카운터로서도, 학자로서도......"
L28_1.m_fTalkTime = 0.03
L28_1.m_Talk_JPN = "カウンターとしても、学者としても……"
L28_1.m_Talk_ENG = "As a Counter, a scholar,"
L28_1.m_Talk_TWN = "不管是作為一個制裁者，還是一個學者……"
L28_1.m_Talk_THA = "ทั้งในฐานะเคาน์เตอร์ นักวิชาการ"
L28_1.m_Talk_VTN = "Là một Counter, một học giả,"
L28_1.m_Talk_SCN = "不管是作为一个制裁者，一个学者……"
L28_1.m_Talk_DEU = "Als Counter, als Gelehrter …"
L28_1.m_Talk_FRA = "Comme Counter, comme savant,"
L29_1 = {}
L29_1.m_CutScenKey_Talk = "EP5_ACT1_PROLOGUE@29#Talk"
L29_1.m_CutScenProcessKey = 29
L29_1.m_CutScenID = 159
L29_1.m_CutScenStrID = "EP5_ACT1_PROLOGUE"
L29_1.m_bWaitClick = true
L29_1.m_fWaitTime = 0
L29_1.m_CharStrID = "JOHN_MASON_NULL_NULL"
L29_1.m_Pos = "C"
L29_1.m_Talk_KOREA = "그리고 형제로서도."
L29_1.m_fTalkTime = 0.03
L29_1.m_Talk_JPN = "そして、兄としても。"
L29_1.m_Talk_ENG = "and as a brother."
L30_1 = "還有作為兄弟。"
L29_1.m_Talk_TWN = L30_1
L30_1 = "และพี่ชาย"
L29_1.m_Talk_THA = L30_1
L30_1 = "và như một người anh em."
L29_1.m_Talk_VTN = L30_1
L30_1 = "还是作为兄弟。"
L29_1.m_Talk_SCN = L30_1
L30_1 = "… und als Bruder."
L29_1.m_Talk_DEU = L30_1
L30_1 = "et comme frère."
L29_1.m_Talk_FRA = L30_1
L30_1 = {}
L31_1 = "EP5_ACT1_PROLOGUE@30#Talk"
L30_1.m_CutScenKey_Talk = L31_1
L31_1 = 30
L30_1.m_CutScenProcessKey = L31_1
L30_1.m_CutScenID = 159
L30_1.m_CutScenStrID = "EP5_ACT1_PROLOGUE"
L30_1.m_bWaitClick = true
L30_1.m_fWaitTime = 0
L30_1.m_CharStrID = "JOHN_MASON_NULL_NULL"
L30_1.m_Pos = "C"
L31_1 = "내가 용병 노릇을 그만두지 못하는 건......"
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "俺が傭兵を辞められねえのは……"
L30_1.m_Talk_JPN = L31_1
L31_1 = "The reason I'm still in the mercenary business"
L30_1.m_Talk_ENG = L31_1
L31_1 = "我之所以無法放棄傭兵的工作....　"
L30_1.m_Talk_TWN = L31_1
L31_1 = "สาเหตุที่ผมยังอยู่ในวงการทหารรับจ้าง"
L30_1.m_Talk_THA = L31_1
L31_1 = "Lý do tôi vẫn tham gia kinh doanh lính đánh thuê"
L30_1.m_Talk_VTN = L31_1
L31_1 = "我之所以不能放弃佣兵的工作。"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Das ist der Grund, warum ich noch im Söldnergeschäft tätig bin:"
L30_1.m_Talk_DEU = L31_1
L31_1 = "Si je suis toujours dans le milieu du mercenariat,"
L30_1.m_Talk_FRA = L31_1
L31_1 = {}
L32_1 = "EP5_ACT1_PROLOGUE@31#Talk"
L31_1.m_CutScenKey_Talk = L32_1
L32_1 = 31
L31_1.m_CutScenProcessKey = L32_1
L31_1.m_CutScenID = 159
L31_1.m_CutScenStrID = "EP5_ACT1_PROLOGUE"
L31_1.m_bWaitClick = true
L31_1.m_fWaitTime = 0
L31_1.m_CharStrID = "JOHN_MASON_NULL_NULL"
L31_1.m_Pos = "C"
L32_1 = "그런 형의 죽음을 도저히 받아들일 수 없었기 때문이야."
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "そんな兄貴の死を到底受け入れることができないからなんだ。"
L31_1.m_Talk_JPN = L32_1
L32_1 = "is that I still can't accept Ian's death."
L31_1.m_Talk_ENG = L32_1
L32_1 = "是因為我無法接受哥哥的死亡。"
L31_1.m_Talk_TWN = L32_1
L32_1 = "ก็เพราะยังทำใจยอมรับความตายของเอียนไม่ได้"
L31_1.m_Talk_THA = L32_1
L32_1 = "là tôi vì vẫn không thể chấp nhận được cái chết của Ian."
L31_1.m_Talk_VTN = L32_1
L32_1 = "是因为我无法接受哥哥的死亡。"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Ich kann Ians Tod immer noch nicht akzeptieren."
L31_1.m_Talk_DEU = L32_1
L32_1 = "c'est parce que je n'arrive pas à admettre la mort de Ian."
L31_1.m_Talk_FRA = L32_1
L32_1 = {}
L33_1 = "EP5_ACT1_PROLOGUE@32#Talk"
L32_1.m_CutScenKey_Talk = L33_1
L33_1 = 32
L32_1.m_CutScenProcessKey = L33_1
L32_1.m_CutScenID = 159
L32_1.m_CutScenStrID = "EP5_ACT1_PROLOGUE"
L32_1.m_bWaitClick = true
L32_1.m_fWaitTime = 0
L32_1.m_CharStrID = "JOHN_MASON_NULL_NULL"
L32_1.m_Pos = "C"
L33_1 = "그래서 형의 죽음과 관련된 비밀이라면 뭐든 파헤치기 시작했고......"
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "兄貴の死と関係のあることなら、何でも調べてきたが……"
L32_1.m_Talk_JPN = L33_1
L33_1 = "I tried to dig into anything that even seemed remotely related to his death,"
L32_1.m_Talk_ENG = L33_1
L33_1 = "所以只要是與我哥的死亡相關的秘密，我都會開始著手調查……"
L32_1.m_Talk_TWN = L33_1
L33_1 = "ผมพยายามขุดทุกอย่างที่พอจะดูเกี่ยงข้องกับความตายของเขาแม้จะเพียงเล็กน้อย"
L32_1.m_Talk_THA = L33_1
L33_1 = "Tôi đã cố gắng tìm hiểu bất cứ điều gì thậm chí không có liên quan lắm đến cái chết của anh ấy,"
L32_1.m_Talk_VTN = L33_1
L33_1 = "所以只要是与我哥的死亡相关的信息，我都会开始着手调查……"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Ich habe versucht, alles zu recherchieren, was auch nur im Entferntesten mit seinem Tod zu tun haben könnte."
L32_1.m_Talk_DEU = L33_1
L33_1 = "J'ai essayé de fouiller dans tout ce qui semblait avoir un lien, même lointain, avec sa mort,"
L32_1.m_Talk_FRA = L33_1
L33_1 = {}
L34_1 = "EP5_ACT1_PROLOGUE@33#Talk"
L33_1.m_CutScenKey_Talk = L34_1
L34_1 = 33
L33_1.m_CutScenProcessKey = L34_1
L33_1.m_CutScenID = 159
L33_1.m_CutScenStrID = "EP5_ACT1_PROLOGUE"
L33_1.m_bWaitClick = true
L33_1.m_fWaitTime = 0
L33_1.m_CharStrID = "JOHN_MASON_NULL_NULL"
L33_1.m_Pos = "C"
L34_1 = "최근에 형의 동료였던 어떤 여자의 도움을 받아서 형이 남긴 유언을 입수하게 됐지."
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "最近、兄貴の元同僚だった女性の協力で、兄貴の遺言を手に入れたんだ。"
L33_1.m_Talk_JPN = L34_1
L34_1 = "and I ended up coming across his will, with the help of a woman who used to work with him."
L33_1.m_Talk_ENG = L34_1
L34_1 = "最近，我受到哥哥以前女同事的幫助，得到了哥哥留下的遺言。"
L33_1.m_Talk_TWN = L34_1
L34_1 = "แล้วสุดท้ายผมก็พบพินัยกรรมของเขา ด้วยความช่วยเหลือของผู้หญิงที่เคยร่วมงานกับเขา"
L33_1.m_Talk_THA = L34_1
L34_1 = "và cuối cùng tôi đã tìm thấy di chúc của anh ấy, với sự giúp đỡ của một người phụ nữ từng làm việc với anh ấy."
L33_1.m_Talk_VTN = L34_1
L34_1 = "最近，我受到哥哥以前的女同事的帮助，得到了哥哥留下的遗言。"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Mit Hilfe einer Frau, die mit ihm zusammenarbeitete, stieß ich schließlich auf sein Testament."
L33_1.m_Talk_DEU = L34_1
L34_1 = "et j'ai fini par trouver ce testament, avec l'aide d'une femme qui avait travaillé avec lui."
L33_1.m_Talk_FRA = L34_1
L34_1 = {}
L35_1 = "EP5_ACT1_PROLOGUE@34#Talk"
L34_1.m_CutScenKey_Talk = L35_1
L35_1 = 34
L34_1.m_CutScenProcessKey = L35_1
L34_1.m_CutScenID = 159
L34_1.m_CutScenStrID = "EP5_ACT1_PROLOGUE"
L34_1.m_bWaitClick = true
L34_1.m_fWaitTime = 0
L34_1.m_CharStrID = "JOOSHIYOON_FENRIR_NULL_NULL"
L34_1.m_Pos = "C"
L35_1 = "유언이라......"
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "遺言ですか……"
L34_1.m_Talk_JPN = L35_1
L35_1 = "A will, huh?"
L34_1.m_Talk_ENG = L35_1
L35_1 = "遺言啊……"
L34_1.m_Talk_TWN = L35_1
L35_1 = "พินัยกรรมเหรอ"
L34_1.m_Talk_THA = L35_1
L35_1 = "Một di chúc sao?"
L34_1.m_Talk_VTN = L35_1
L35_1 = "遗言啊……"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Ein Testament?"
L34_1.m_Talk_DEU = L35_1
L35_1 = "Un testament ?"
L34_1.m_Talk_FRA = L35_1
L35_1 = {}
L36_1 = "EP5_ACT1_PROLOGUE@35#Talk"
L35_1.m_CutScenKey_Talk = L36_1
L36_1 = 35
L35_1.m_CutScenProcessKey = L36_1
L35_1.m_CutScenID = 159
L35_1.m_CutScenStrID = "EP5_ACT1_PROLOGUE"
L35_1.m_bWaitClick = true
L35_1.m_fWaitTime = 0
L35_1.m_CharStrID = "JOOSHIYOON_FENRIR_NULL_NULL"
L35_1.m_Pos = "C"
L36_1 = "무슨 내용이었죠?"
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "どんな内容でしたか？"
L35_1.m_Talk_JPN = L36_1
L36_1 = "What was it about?"
L35_1.m_Talk_ENG = L36_1
L36_1 = "是什麼內容呢？"
L35_1.m_Talk_TWN = L36_1
L36_1 = "มันบอกว่าไง?"
L35_1.m_Talk_THA = L36_1
L36_1 = "Nội dung của nó là gì?"
L35_1.m_Talk_VTN = L36_1
L36_1 = "是什么内容呢？"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Worum ging es dabei?"
L35_1.m_Talk_DEU = L36_1
L36_1 = "Il y avait quoi dedans ?"
L35_1.m_Talk_FRA = L36_1
L36_1 = {}
L37_1 = "EP5_ACT1_PROLOGUE@36#Talk"
L36_1.m_CutScenKey_Talk = L37_1
L37_1 = 36
L36_1.m_CutScenProcessKey = L37_1
L36_1.m_CutScenID = 159
L36_1.m_CutScenStrID = "EP5_ACT1_PROLOGUE"
L36_1.m_bWaitClick = true
L36_1.m_fWaitTime = 0
L37_1 = "UNIT_LAUGH"
L36_1.m_Face = L37_1
L36_1.m_CharStrID = "JOHN_MASON_NULL_NULL"
L36_1.m_Pos = "C"
L37_1 = "직접 보라고. 본인이 설명해 줄 테니까."
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "本人が説明してくれるから、直接見てみろ。"
L36_1.m_Talk_JPN = L37_1
L37_1 = "See for yourself. He's going to explain himself."
L36_1.m_Talk_ENG = L37_1
L37_1 = "直接去看吧，本人會解釋清楚的。"
L36_1.m_Talk_TWN = L37_1
L37_1 = "ดูเอาเองสิ เขาจะอธิบายตัวเอง"
L36_1.m_Talk_THA = L37_1
L37_1 = "Hãy xem đi. Anh ấy sẽ tự giải thích."
L36_1.m_Talk_VTN = L37_1
L37_1 = "直接去看吧，本人会解释清楚的。"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Schau selbst … Er wird es erklären."
L36_1.m_Talk_DEU = L37_1
L37_1 = "Regarde par toi-même. Il va s'expliquer."
L36_1.m_Talk_FRA = L37_1
