L40_1 = "CUTSCENE_TALK_02"
L39_1.m_StartBGMFileName = L40_1
L39_1.m_CharStrID = "IAN_EXTRA_NULL_NULL"
L40_1 = "우선은...... 그래."
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "まずは……そうだな。"
L39_1.m_Talk_JPN = L40_1
L40_1 = "Let's see... Right."
L39_1.m_Talk_ENG = L40_1
L40_1 = "首先……對了。"
L39_1.m_Talk_TWN = L40_1
L40_1 = "ไหนดูซิ... เอาละ"
L39_1.m_Talk_THA = L40_1
L40_1 = "Hãy xem nào... Được."
L39_1.m_Talk_VTN = L40_1
L40_1 = "首先……"
L39_1.m_Talk_SCN = L40_1
L40_1 = "Mal sehen … Okay."
L39_1.m_Talk_DEU = L40_1
L40_1 = "Bon... Alors."
L39_1.m_Talk_FRA = L40_1
L40_1 = {}
L41_1 = "EP5_ACT1_PROLOGUE@40#Talk"
L40_1.m_CutScenKey_Talk = L41_1
L41_1 = 40
L40_1.m_CutScenProcessKey = L41_1
L40_1.m_CutScenID = 159
L40_1.m_CutScenStrID = "EP5_ACT1_PROLOGUE"
L40_1.m_bWaitClick = true
L40_1.m_fWaitTime = 0
L40_1.m_CharStrID = "IAN_EXTRA_NULL_NULL"
L41_1 = "옛날 이야기부터 시작해야겠군."
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "昔話から始めるとしようか。"
L40_1.m_Talk_JPN = L41_1
L41_1 = "I should start with what happened to me a long time ago."
L40_1.m_Talk_ENG = L41_1
L41_1 = "要從很久之前開始說起了。"
L40_1.m_Talk_TWN = L41_1
L41_1 = "ผมควรเริ่มด้วยการเล่าถึงสิ่งที่เกิดขึ้นกับผมเมื่อนานมาแล้ว"
L40_1.m_Talk_THA = L41_1
L41_1 = "Tôi sẽ bắt đầu với những điều đã xảy ra với tôi cách đây rất lâu."
L40_1.m_Talk_VTN = L41_1
L41_1 = "要从很久之前开始说起了。"
L40_1.m_Talk_SCN = L41_1
L41_1 = "Ich sollte mit etwas beginnen, was mir vor langer Zeit passierte."
L40_1.m_Talk_DEU = L41_1
L41_1 = "Je devrais commencer par ce qui m'est arrivé il y a longtemps."
L40_1.m_Talk_FRA = L41_1
L41_1 = {}
L42_1 = "EP5_ACT1_PROLOGUE@41#Talk"
L41_1.m_CutScenKey_Talk = L42_1
L42_1 = 41
L41_1.m_CutScenProcessKey = L42_1
L41_1.m_CutScenID = 159
L41_1.m_CutScenStrID = "EP5_ACT1_PROLOGUE"
L41_1.m_bWaitClick = true
L41_1.m_fWaitTime = 0
L41_1.m_CharStrID = "IAN_EXTRA_NULL_NULL"
L42_1 = "몇 년 전쯤이었나......?"
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "何年前だったかな……？"
L41_1.m_Talk_JPN = L42_1
L42_1 = "It was several years ago"
L41_1.m_Talk_ENG = L42_1
L42_1 = "大概是幾年前吧？"
L41_1.m_Talk_TWN = L42_1
L42_1 = "มันผ่านมาหลายปีแล้ว"
L41_1.m_Talk_THA = L42_1
L42_1 = "Vài năm trước,"
L41_1.m_Talk_VTN = L42_1
L42_1 = "大概是几年前吧？"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Es geschah vor einigen Jahren."
L41_1.m_Talk_DEU = L42_1
L42_1 = "C'était il y a plusieurs années,"
L41_1.m_Talk_FRA = L42_1
L42_1 = {}
L43_1 = "EP5_ACT1_PROLOGUE@42#Talk"
L42_1.m_CutScenKey_Talk = L43_1
L43_1 = 42
L42_1.m_CutScenProcessKey = L43_1
L42_1.m_CutScenID = 159
L42_1.m_CutScenStrID = "EP5_ACT1_PROLOGUE"
L42_1.m_bWaitClick = true
L42_1.m_fWaitTime = 0
L42_1.m_CharStrID = "IAN_EXTRA_NULL_NULL"
L43_1 = "바에서 진탕 마시고 뻗어 있는 내게 한 남자가 찾아왔지."
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "バーで酔いつぶれている私に、ある男が近づいてきたんだ。"
L42_1.m_Talk_JPN = L43_1
L43_1 = "when this man came looking for me while I was drunk as hell at a bar."
L42_1.m_Talk_ENG = L43_1
L43_1 = "我在酒吧裡喝得爛醉，一個男人朝我走了過來。"
L42_1.m_Talk_TWN = L43_1
L43_1 = "ตอนที่ชายคนหนึ่งมาตามหาผม ตอนที่ผมกำลังเมาแอ๋อยู่ที่บาร์"
L42_1.m_Talk_THA = L43_1
L43_1 = "khi người đàn ông này đến tìm tôi trong khi tôi đang say như điếu đổ tại một quán bar."
L42_1.m_Talk_VTN = L43_1
L43_1 = "我在酒吧里喝得烂醉，一个男人朝我走了过来。"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Ein Mann suchte mich auf, als ich gerade sturzbetrunken in einer Bar war."
L42_1.m_Talk_DEU = L43_1
L43_1 = "un homme est venu me trouver dans un bar alors que j'étais complètement saoul."
L42_1.m_Talk_FRA = L43_1
L43_1 = {}
L44_1 = "EP5_ACT1_PROLOGUE@43#Talk"
L43_1.m_CutScenKey_Talk = L44_1
L44_1 = 43
L43_1.m_CutScenProcessKey = L44_1
L43_1.m_CutScenID = 159
L43_1.m_CutScenStrID = "EP5_ACT1_PROLOGUE"
L43_1.m_bWaitClick = true
L43_1.m_fWaitTime = 0
L43_1.m_CharStrID = "IAN_EXTRA_NULL_NULL"
L44_1 = "<color=#ffd34c>미스터 레지날드</color>라고 자기를 소개한 그 남자는 대뜸 내게 세상을 바꿔 볼 생각이 없느냐고 물어 보더군."
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "<color=#ffd34c>ミスター・レジナルド</color>と名乗ったその男は、いきなり私に、世界を変えてみるつもりはないかと尋ねてきた。"
L43_1.m_Talk_JPN = L44_1
L44_1 = "He called himself <color=#ffd34c>Mr. Reginald</color> and asked me if I was interested in changing the world."
L43_1.m_Talk_ENG = L44_1
L44_1 = "那個人自稱是<color=#ffd34c>傳奇先生</color>，並問我有沒有想要改變世界的想法。"
L43_1.m_Talk_TWN = L44_1
L44_1 = "เขาเรียกตัวเองว่า<color=#ffd34c>คุณเรจินัลด์</color> และถามผมว่าผมสนใจจะเปลี่ยนโลกไหม "
L43_1.m_Talk_THA = L44_1
L44_1 = "Anh ta tự gọi mình là <color=#ffd34c>Mr. Reginald</color> và hỏi tôi liệu tôi có muốn thay đổi thế giới không."
L43_1.m_Talk_VTN = L44_1
L44_1 = "那个人自称是<color=#ffd34c>传奇先生</color>，并问道：我有没有改变世界的想法。"
L43_1.m_Talk_SCN = L44_1
L44_1 = "Er nannte sich <color=#ffd34c>Mr. Reginald</color> und fragte mich, ob ich daran interessiert sei, die Welt zu verändern."
L43_1.m_Talk_DEU = L44_1
L44_1 = "Il se faisait appeler <color=#ffd34c>Monsieur Reginald</color>, et m'a demandé si je voulais changer le monde."
L43_1.m_Talk_FRA = L44_1
L44_1 = {}
L45_1 = "EP5_ACT1_PROLOGUE@44#Talk"
L44_1.m_CutScenKey_Talk = L45_1
L45_1 = 44
L44_1.m_CutScenProcessKey = L45_1
L44_1.m_CutScenID = 159
L44_1.m_CutScenStrID = "EP5_ACT1_PROLOGUE"
L44_1.m_bWaitClick = true
L44_1.m_fWaitTime = 0
L44_1.m_CharStrID = "IAN_EXTRA_NULL_NULL"
L45_1 = "처음에는 웬 사기꾼인가 하고 생각했는데......"
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "最初は詐欺師まがいの奴かと思ったが……"
L44_1.m_Talk_JPN = L45_1
L45_1 = "I initially thought he was some kind of a scammer,"
L44_1.m_Talk_ENG = L45_1
L45_1 = "我剛開始覺得他是個騙子。"
L44_1.m_Talk_TWN = L45_1
L45_1 = "ตอนแรกผมนึกว่าเขาเป็นพวกนักต้มตุ๋น"
L44_1.m_Talk_THA = L45_1
L45_1 = "Ban đầu tôi nghĩ anh ta là một kẻ lừa đảo,"
L44_1.m_Talk_VTN = L45_1
L45_1 = "我刚开始觉得他就是个骗子。"
L44_1.m_Talk_SCN = L45_1
L45_1 = "Anfangs hielt ich ihn für eine Art Hochstapler."
L44_1.m_Talk_DEU = L45_1
L45_1 = "Au début, j'ai pensé que c'était une arnaque,"
L44_1.m_Talk_FRA = L45_1
L45_1 = {}
L46_1 = "EP5_ACT1_PROLOGUE@45#Talk"
L45_1.m_CutScenKey_Talk = L46_1
L46_1 = 45
L45_1.m_CutScenProcessKey = L46_1
L45_1.m_CutScenID = 159
L45_1.m_CutScenStrID = "EP5_ACT1_PROLOGUE"
L45_1.m_bWaitClick = true
L45_1.m_fWaitTime = 0
L45_1.m_CharStrID = "IAN_EXTRA_NULL_NULL"
L46_1 = "이 친구가 보여 준 자료를 보고는 정신이 확 깨 버렸지 뭐야."
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "その男が差し出した資料を見て、一気に目が覚めたさ。"
L45_1.m_Talk_JPN = L46_1
L46_1 = "but what he showed me opened my eyes."
L45_1.m_Talk_ENG = L46_1
L46_1 = "但當這位朋友把資料拿給我看時，我整個人完全清醒了過來。"
L45_1.m_Talk_TWN = L46_1
L46_1 = "แต่สิ่งที่เขาให้ผมดูนั้นเปิดโลกของผมมาก"
L45_1.m_Talk_THA = L46_1
L46_1 = "nhưng những gì anh ấy cho tôi thấy đã làm tôi bừng tỉnh."
L45_1.m_Talk_VTN = L46_1
L46_1 = "但看到这个朋友给我发的资料就被震惊到了。"
L45_1.m_Talk_SCN = L46_1
L46_1 = "Aber dann zeigte er mir etwas, das mir die Augen öffnete."
L45_1.m_Talk_DEU = L46_1
L46_1 = "mais ce qu'il m'a montré m'a ouvert les yeux."
L45_1.m_Talk_FRA = L46_1
L46_1 = {}
L47_1 = "EP5_ACT1_PROLOGUE@46#Talk"
L46_1.m_CutScenKey_Talk = L47_1
L47_1 = 46
L46_1.m_CutScenProcessKey = L47_1
L46_1.m_CutScenID = 159
L46_1.m_CutScenStrID = "EP5_ACT1_PROLOGUE"
L46_1.m_bWaitClick = true
L46_1.m_fWaitTime = 0
L46_1.m_CharStrID = "IAN_EXTRA_NULL_NULL"
L47_1 = "그건 도저히 생물이 살 수 없는 고밀도 침식파 환경에서 멀쩡히 뛰어 놀고 있는 실험용 생쥐들의 모습이었어."
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "あれは生き物が到底生存できない高密度侵食波の環境下で、\n普通に走り回っている実験用マウスの姿だった。"
L46_1.m_Talk_JPN = L47_1
L47_1 = "It was footage of lab mice running around casually in an environment where the Corruption level had been raised beyond lethal limits."
L46_1.m_Talk_ENG = L47_1
L47_1 = "那是一個在生物根本無法生存的高密度侵蝕波環境中，一群實驗老鼠在玩耍的畫面。"
L46_1.m_Talk_TWN = L47_1
L47_1 = "มันคือวิดีโอของหนูทดลองในห้องแล็บที่กำลังวิ่งไปมาอย่างสบายๆ ในสภาพแวดล้อมที่ระดับการคอร์รัปชั่นสูงเกินขีดจำกัดที่ปลอดภัย"
L46_1.m_Talk_THA = L47_1
L47_1 = "Đó là cảnh những con chuột trong phòng thí nghiệm tình cờ chạy tán loạn ở một môi trường mà mức độ Ăn Mòn đã được nâng lên vượt quá giới hạn chết người."
L46_1.m_Talk_VTN = L47_1
L47_1 = "那是一个在生物根本无法生存的高密度侵蚀波环境中，一群实验老鼠在正常的玩耍的画面。"
L46_1.m_Talk_SCN = L47_1
L47_1 = "Es waren Aufnahmen von Labormäusen – sie liefen in einer Umgebung herum, deren Verderbnisgrad weit über tödliche Grenzen erhöht worden war."
L46_1.m_Talk_DEU = L47_1
L47_1 = "C'était une vidéo dans laquelle une souris de laboratoire se promenait en toute insouciance dans un environnement dont les niveaux de corruption avaient été poussés bien au-delà de la limite létale."
L46_1.m_Talk_FRA = L47_1
L47_1 = {}
