L51_1 = "EP5_ACT1_PROLOGUE@50#Talk"
L50_1.m_CutScenKey_Talk = L51_1
L51_1 = 50
L50_1.m_CutScenProcessKey = L51_1
L50_1.m_CutScenID = 159
L50_1.m_CutScenStrID = "EP5_ACT1_PROLOGUE"
L50_1.m_bWaitClick = true
L50_1.m_fWaitTime = 0
L50_1.m_CharStrID = "IAN_EXTRA_NULL_NULL"
L51_1 = "그 남자는 이면세계를 사람이 살 수 있는 곳으로 개조하는 방법을 연구 중이라고 하더군."
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "あの男は、裏世界の環境を人間が住めるようにしようと研究しているのだと言った。"
L50_1.m_Talk_JPN = L51_1
L51_1 = "The man said he was researching ways to turn the Counterside into an inhabitable area."
L50_1.m_Talk_ENG = L51_1
L51_1 = "那個男人說他正在研究把異界改造成人們能夠生活的地方。"
L50_1.m_Talk_TWN = L51_1
L51_1 = "ชายคนนั้นบอกว่าเขากำลังค้นคว้าวิธีที่จะทำให้เคาน์เตอร์ไซด์กลายเป็นพื้นที่ที่อาศัยอยู่ได้"
L50_1.m_Talk_THA = L51_1
L51_1 = "Người đàn ông nói rằng anh ta đang nghiên cứu các cách để biến Counterside thành một khu vực có thể sinh sống."
L50_1.m_Talk_VTN = L51_1
L51_1 = "那个男人说他正在研究把异界改造为人们能够得以生活的地方。"
L50_1.m_Talk_SCN = L51_1
L51_1 = "Der Mann sagte, er erforsche Möglichkeiten, die Counterside in bewohnbares Gebiet zu verwandeln."
L50_1.m_Talk_DEU = L51_1
L51_1 = "L'homme prétendait rechercher un moyen de transformer le Contremonde en zone habitable."
L50_1.m_Talk_FRA = L51_1
