L3_1 = "EP5_ACT1_PROLOGUE@52#Talk"
L2_1.m_CutScenKey_Talk = L3_1
L3_1 = 52
L2_1.m_CutScenProcessKey = L3_1
L2_1.m_CutScenID = 159
L2_1.m_CutScenStrID = "EP5_ACT1_PROLOGUE"
L2_1.m_bWaitClick = true
L2_1.m_fWaitTime = 0
L3_1 = "COUNTERSIDE_FOREST"
L2_1.m_BGFileName = L3_1
L2_1.m_bFadeIn = true
L3_1 = 0.4
L2_1.m_fFadeTime = L3_1
L2_1.m_CharStrID = "IAN_EXTRA_NULL_NULL"
L3_1 = "시간은 걸리겠지만, 인류가 뻗어나갈 수 있는 신천지를 개척해서......"
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "時間はかかるだろうが、人類が生き延びられる新天地を切り開いて……"
L2_1.m_Talk_JPN = L3_1
L3_1 = "He added that no matter how long it'd take, he was determined to cultivate the place"
L2_1.m_Talk_ENG = L3_1
L3_1 = "雖然需要時間，但他想開拓人類得以延續的新天地。"
L2_1.m_Talk_TWN = L3_1
L3_1 = "เขาเสริมด้วยว่า ไม่ว่าจะใช้เวลานานแค่ไหน เขาก็มุ่งมั่นที่จะบ่มเพาะที่นั่น"
L2_1.m_Talk_THA = L3_1
L3_1 = "Anh ấy nói thêm rằng cho dù mất bao lâu, anh ấy vẫn quyết tâm biến nơi này"
L2_1.m_Talk_VTN = L3_1
L3_1 = "虽然需要时间，但他想开拓人类可以得以延续的新天地。"
L2_1.m_Talk_SCN = L3_1
L3_1 = "Er fügte hinzu, er sei entschlossen, die Counterside in ein Paradies zu verwandeln,"
L2_1.m_Talk_DEU = L3_1
L3_1 = "Il a même ajouté que peu importait le temps que cela prendrait, il était déterminé à transformer le Contremonde"
L2_1.m_Talk_FRA = L3_1
L3_1 = {}
L4_1 = "EP5_ACT1_PROLOGUE@53#Talk"
L3_1.m_CutScenKey_Talk = L4_1
L4_1 = 53
L3_1.m_CutScenProcessKey = L4_1
L3_1.m_CutScenID = 159
L3_1.m_CutScenStrID = "EP5_ACT1_PROLOGUE"
L3_1.m_bWaitClick = true
L3_1.m_fWaitTime = 0
L3_1.m_CharStrID = "IAN_EXTRA_NULL_NULL"
L4_1 = "전쟁도, 기아도 없는 신세계를 만드는 것이 자신의 목표라고."
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "戦争も、飢饉もない新世界を作るのが自分の目標だと。"
L3_1.m_Talk_JPN = L4_1
L4_1 = "into a paradise where there would be no war or hunger."
L3_1.m_Talk_ENG = L4_1
L4_1 = "他說他的目標，是打造一個沒有戰爭、沒有饑餓的新世界。"
L3_1.m_Talk_TWN = L4_1
L4_1 = "ให้กลายเป็นแดนสวรรค์ที่ปราศจากสงครามหรือความหิวโหย"
L3_1.m_Talk_THA = L4_1
L4_1 = "thành một thiên đường nơi sẽ không có chiến tranh hay nghèo đói."
L3_1.m_Talk_VTN = L4_1
L4_1 = "他的目标是打造一个没有战争、没有饥荒的新世界。"
L3_1.m_Talk_SCN = L4_1
L4_1 = "in dem es weder Krieg noch Hunger gibt – egal, wie lange es dauern würde."
L3_1.m_Talk_DEU = L4_1
L4_1 = "en un paradis où il n'y aurait ni guerre ni famine."
L3_1.m_Talk_FRA = L4_1
