L7_1 = "EP5_ACT1_PROLOGUE@56#Talk"
L6_1.m_CutScenKey_Talk = L7_1
L7_1 = 56
L6_1.m_CutScenProcessKey = L7_1
L6_1.m_CutScenID = 159
L6_1.m_CutScenStrID = "EP5_ACT1_PROLOGUE"
L6_1.m_bWaitClick = true
L6_1.m_fWaitTime = 0
L6_1.m_CharStrID = "IAN_EXTRA_NULL_NULL"
L7_1 = "하하하...... 나 같은 이상주의자에겐 도저히 피할 수 없는 미끼였지."
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "ハハハ、私のような理想主義者には、とても魅力的な餌だったよ。"
L6_1.m_Talk_JPN = L7_1
L7_1 = "Hah hah... It was an offer that an idealist like me couldn't refuse."
L6_1.m_Talk_ENG = L7_1
L7_1 = "哈哈哈……對於像我這樣的理想主義者來說，這還真是個無法拒絕的誘餌呢。"
L6_1.m_Talk_TWN = L7_1
L7_1 = "ฮ่าๆ... นั่นเป็นข้อเสนอที่นักอุดมคติอย่างผมไม่อาจปฏิเสธได้"
L6_1.m_Talk_THA = L7_1
L7_1 = "Hah hah ... Đó là lời đề nghị mà một người theo chủ nghĩa lý tưởng như tôi không thể từ chối."
L6_1.m_Talk_VTN = L7_1
L7_1 = "哈哈哈……对于像我这样的一个理想主义者来说，可真是让人无法拒绝呢。"
L6_1.m_Talk_SCN = L7_1
L7_1 = "Das war ein Angebot, das ein Idealist wie ich nicht ablehnen konnte."
L6_1.m_Talk_DEU = L7_1
L7_1 = "Ha ha... C'était une offre qu'un idéaliste comme moi ne pouvait pas refuser."
L6_1.m_Talk_FRA = L7_1
L7_1 = {}
L8_1 = "EP5_ACT1_PROLOGUE@57#Talk"
L7_1.m_CutScenKey_Talk = L8_1
L8_1 = 57
L7_1.m_CutScenProcessKey = L8_1
L7_1.m_CutScenID = 159
L7_1.m_CutScenStrID = "EP5_ACT1_PROLOGUE"
L7_1.m_bWaitClick = true
L7_1.m_fWaitTime = 0
L7_1.m_CharStrID = "IAN_EXTRA_NULL_NULL"
L8_1 = "이름도 꽤 멋졌어. 이면세계를 낙원으로 바꾸는 자들......"
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "タイトルのセンスもなかなかでね、「裏世界を楽園に変える者たち」……"
L7_1.m_Talk_JPN = L8_1
L8_1 = "Even the name of the group was cool. The ones who will change the Counterside into a paradise..."
L7_1.m_Talk_ENG = L8_1
L8_1 = "他們的名字也很酷，將異界改造成樂園的人…"
L7_1.m_Talk_TWN = L8_1
L8_1 = "แม้แต่ชื่อของกลุ่มก็ยังเจ๋งเลย กลุ่มคนที่จะเปลี่ยนเคาน์เตอร์ไซด์เป็นแดนสวรรค์..."
L7_1.m_Talk_THA = L8_1
L8_1 = "Ngay cả cái tên của nhóm cũng rất ngầu. Những người sẽ biến Counterside thành một thiên đường ..."
L7_1.m_Talk_VTN = L8_1
L8_1 = "名字也很有范。将异界打造成乐土者……"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Schon der Name war cool – die Gruppe, die die Counterside in ein Paradies verwandeln wollte, nannte sich:"
L7_1.m_Talk_DEU = L8_1
L8_1 = "Même le nom était cool. Ceux qui allaient faire du Contremonde un paradis..."
L7_1.m_Talk_FRA = L8_1
L8_1 = {}
