L11_1 = "리플레이서......! 설마......?"
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "リプレイサー……！　まさか……？"
L10_1.m_Talk_JPN = L11_1
L11_1 = "R-Replacers? No, he's not saying..."
L10_1.m_Talk_ENG = L11_1
L11_1 = "克隆集團……！ 難道……？"
L10_1.m_Talk_TWN = L11_1
L11_1 = "ระ-รีเพลสเซอร์เหรอ? ไม่นะ เขาไม่ได้จะบอกว่า..."
L10_1.m_Talk_THA = L11_1
L11_1 = "N-Người Nhân Bản? Không, anh ta không nói..."
L10_1.m_Talk_VTN = L11_1
L11_1 = "克隆集团……?! 难道……?"
L10_1.m_Talk_SCN = L11_1
L11_1 = "R-Replacer? Soll das heißen …"
L10_1.m_Talk_DEU = L11_1
L11_1 = "L-Les substituts ? Non, il faisait..."
L10_1.m_Talk_FRA = L11_1
