L12_1 = "EP5_ACT1_PROLOGUE@61#Talk"
L11_1.m_CutScenKey_Talk = L12_1
L12_1 = 61
L11_1.m_CutScenProcessKey = L12_1
L11_1.m_CutScenID = 159
L11_1.m_CutScenStrID = "EP5_ACT1_PROLOGUE"
L11_1.m_bWaitClick = true
L11_1.m_fWaitTime = 0
L11_1.m_CharStrID = "JOHN_MASON_NULL_NULL"
L12_1 = "쉿. 이야기는 끝까지 보고 나서 해도 늦지 않아."
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "しっ、最後まで聞いてから話しても遅くないぞ。"
L11_1.m_Talk_JPN = L12_1
L12_1 = "Shh. Save your thoughts for after the end."
L11_1.m_Talk_ENG = L12_1
L12_1 = "噓，把話聽完再發作也不遲。"
L11_1.m_Talk_TWN = L12_1
L12_1 = "จุ๊ๆ รอให้เรื่องจบแล้วค่อยพูดสิ"
L11_1.m_Talk_THA = L12_1
L12_1 = "Suỵt. Hãy giữ lại suy nghĩ của bạn cho đến sau khi kết thúc."
L11_1.m_Talk_VTN = L12_1
L12_1 = "嘘。先把话听完。"
L11_1.m_Talk_SCN = L12_1
L12_1 = "Pst … Warte mit deinen Fragen bis zum Ende."
L11_1.m_Talk_DEU = L12_1
L12_1 = "Chut. Garde tes réflexions pour après."
L11_1.m_Talk_FRA = L12_1
