L17_1 = "그리고 한동안은 괜찮았어."
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "それからしばらくの間は良かった。"
L16_1.m_Talk_JPN = L17_1
L17_1 = "Everything was fine, at least for a while."
L16_1.m_Talk_ENG = L17_1
L17_1 = "之後有一段時間還不錯。"
L16_1.m_Talk_TWN = L17_1
L17_1 = "ทุกอย่างราบรื่นดี อย่างน้อยก็สักระยะหนึ่ง"
L16_1.m_Talk_THA = L17_1
L17_1 = "Mọi thứ đều ổn, ít nhất là trong một thời gian."
L16_1.m_Talk_VTN = L17_1
L17_1 = "刚起步的那段时间还不错。"
L16_1.m_Talk_SCN = L17_1
L17_1 = "Alles lief gut, zumindest eine Zeit lang."
L16_1.m_Talk_DEU = L17_1
L17_1 = "Tout s'est bien passé, du moins pendant un certain temps."
L16_1.m_Talk_FRA = L17_1
