L17_1.m_fWaitTime = 0
L17_1.m_CharStrID = "IAN_EXTRA_NULL_NULL"
L18_1 = "민간조직이라고는 믿을 수 없을 정도의 자금 동원력이나 조직력......"
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "民間組織とは思えないほどの資金力や組織力……"
L17_1.m_Talk_JPN = L18_1
L18_1 = "We raised funds like no other private organization could; all the members had a strong sense of unity..."
L17_1.m_Talk_ENG = L18_1
L18_1 = "雖然是民間組織，但它有令人難以置信的資金和組織力....."
L17_1.m_Talk_TWN = L18_1
L18_1 = "เราระดมทุนได้ในแบบที่องค์กรเอกชนอื่นๆ ทำไม่ได้ สมาชิกทุกคนมีสำนึกของความเป็นเอกภาพที่เข้มข้นมาก"
L17_1.m_Talk_THA = L18_1
L18_1 = "Chúng tôi đã gây dựng được những ngân quỹ mà không tổ chức tư nhân nào khác có thể làm được; tất cả các thành viên đều có ý thức đoàn kết mạnh mẽ ..."
L17_1.m_Talk_VTN = L18_1
L18_1 = "虽然是民间组织，但它有着庞大的资金力量和组织力。"
L17_1.m_Talk_SCN = L18_1
L18_1 = "Wir sammelten Gelder wie keine andere private Organisation, und unter den Mitgliedern herrschte ein starkes Gefühl der Zusammengehörigkeit."
L17_1.m_Talk_DEU = L18_1
L18_1 = "Nous avons levé des fonds comme aucune autre organisation privée ne pouvait le faire, tous les participants avaient un grand sens de la cohésion..."
L17_1.m_Talk_FRA = L18_1
L18_1 = {}
L19_1 = "EP5_ACT1_PROLOGUE@68#Talk"
L18_1.m_CutScenKey_Talk = L19_1
L19_1 = 68
L18_1.m_CutScenProcessKey = L19_1
L18_1.m_CutScenID = 159
L18_1.m_CutScenStrID = "EP5_ACT1_PROLOGUE"
L18_1.m_bWaitClick = true
L18_1.m_fWaitTime = 0
L18_1.m_CharStrID = "IAN_EXTRA_NULL_NULL"
L19_1 = "그리고 무엇보다 관리국 환경 연구부서에서 꽤 잘나가는 선임연구원이었던 나도 구경조차 못해 본 구 관리국의 아티팩트급 유물들을 넘치도록 제공해 줬거든."
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "何せ管理局環境研究部署のエリート専任研究員だった私ですら、\n見たこともない旧管理局のアーティファクト級の遺物を山ほど与えてくれたからな。"
L18_1.m_Talk_JPN = L19_1
L19_1 = "And most of all, they provided me with tons of rare artifacts of the Old Administration, which even I, a former senior researcher of the Administration, had never come across before."
L18_1.m_Talk_ENG = L19_1
L19_1 = "而且最重要的是，他們提供了大量舊管理局的人造神器級遺物，是連我這個管理局環境研究部門的上級研究員都從未見過的。"
L18_1.m_Talk_TWN = L19_1
L19_1 = "และเหนือสิ่งอื่นใด พวกเขาให้อาร์ติแฟ็กต์หายากขององค์การบริหารโลกในอดีตกับผมมากมาย ชนิดที่แม้แต่คนอย่างผม ซึ่งเป็นอดีตนักวิจัยอาวุโสขององค์การบริหารโลกก็ยังไม่เคยเห็นมาก่อน"
L18_1.m_Talk_THA = L19_1
L19_1 = "Và hơn hết, họ cung cấp cho tôi hàng tấn di tích quý hiếm của Cục Quản Lý Cũ, những thứ mà ngay cả tôi, một cựu nghiên cứu viên cao cấp của Cục Quản Lý, cũng chưa từng gặp trước đây."
L18_1.m_Talk_VTN = L19_1
L19_1 = "而且，他们给我提供了大量的艺术级遗物，这是身为管理局环境研究部门高级研究员的我也从未见过的。"
L18_1.m_Talk_SCN = L19_1
L19_1 = "Vor allem stellten sie mir haufenweise seltene Artefakte der Alten Administration zur Verfügung, die selbst ich – als einstiger leitender Forscher der Administration – noch nie zuvor gesehen hatte."
L18_1.m_Talk_DEU = L19_1
L19_1 = "Et surtout, on m'a fourni des tonnes d'artefacts rares datant de l'Ancienne Administration dont même moi, ancien chercheur en chef de l'Administration, je ne soupçonnais pas l'existence."
L18_1.m_Talk_FRA = L19_1
L19_1 = {}
