L21_1 = "EP5_ACT1_PROLOGUE@70#Talk"
L20_1.m_CutScenKey_Talk = L21_1
L21_1 = 70
L20_1.m_CutScenProcessKey = L21_1
L20_1.m_CutScenID = 159
L20_1.m_CutScenStrID = "EP5_ACT1_PROLOGUE"
L20_1.m_bWaitClick = true
L20_1.m_fWaitTime = 0
L20_1.m_CharStrID = "IAN_EXTRA_NULL_NULL"
L21_1 = "하지만 시간이 지날수록 이상한 것들이 눈에 뜨이기 시작했어."
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "しかし、時間が経つにつれて妙なものが目につくようになった。"
L20_1.m_Talk_JPN = L21_1
L21_1 = "But as time passed, I started to notice weird things."
L20_1.m_Talk_ENG = L21_1
L21_1 = "但隨著時間的推移，一些奇怪的現象開始映入我的眼簾。"
L20_1.m_Talk_TWN = L21_1
L21_1 = "แต่เมื่อเวลาผ่านไป ผมก็เริ่มสังเกตเห็นสิ่งแปลกๆ"
L20_1.m_Talk_THA = L21_1
L21_1 = "Nhưng khi thời gian trôi qua, tôi bắt đầu nhận thấy những điều kỳ lạ."
L20_1.m_Talk_VTN = L21_1
L21_1 = "但随着时间的推移，一些奇怪的现象开始映入我的眼帘了。"
L20_1.m_Talk_SCN = L21_1
L21_1 = "Doch mit der Zeit fielen mir merkwürdige Dinge auf."
L20_1.m_Talk_DEU = L21_1
L21_1 = "Mais, avec le temps, j'ai commencé à remarquer des choses bizarres."
L20_1.m_Talk_FRA = L21_1
L21_1 = {}
L22_1 = "EP5_ACT1_PROLOGUE@71#Talk"
L21_1.m_CutScenKey_Talk = L22_1
L22_1 = 71
L21_1.m_CutScenProcessKey = L22_1
L21_1.m_CutScenID = 159
L21_1.m_CutScenStrID = "EP5_ACT1_PROLOGUE"
L21_1.m_bWaitClick = true
L21_1.m_fWaitTime = 0
L21_1.m_CharStrID = "IAN_EXTRA_NULL_NULL"
L22_1 = "도무지 출처를 알 수 없는 생체 조직에 대한 실험 자료들이 데이터베이스에 올라왔고......"
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "出所のわからないような生体組織に関する実験資料がデータベースに上がったり……"
L21_1.m_Talk_JPN = L22_1
L22_1 = "There was data from biotests with untraceable sources in the database."
L21_1.m_Talk_ENG = L22_1
L22_1 = "資料庫裡，開始出現了一些完全無法得知來源的生物組織實驗資料。"
L21_1.m_Talk_TWN = L22_1
L22_1 = "มีข้อมูลจากการทดสอบชีวภาพกับแหล่งข้อมูลที่หาร่องรอยไม่ได้อยู่ในฐานข้อมูล"
L21_1.m_Talk_THA = L22_1
L22_1 = "Có dữ liệu về các thí nghiệm sinh học từ các nguồn không thể truy vết trong cơ sở dữ liệu."
L21_1.m_Talk_VTN = L22_1
L22_1 = "数据库里，开始出现了一些完全不知来源的生物组织实验的相关资料。"
L21_1.m_Talk_SCN = L22_1
L22_1 = "In der Datenbank befanden sich Daten aus Biotests mit nicht zurückverfolgbaren Quellen."
L21_1.m_Talk_DEU = L22_1
L22_1 = "La base de données contenait des informations provenant de biotests dont les sources n'étaient pas traçables."
L21_1.m_Talk_FRA = L22_1
L22_1 = {}
L23_1 = "EP5_ACT1_PROLOGUE@72#Talk"
L22_1.m_CutScenKey_Talk = L23_1
L23_1 = 72
L22_1.m_CutScenProcessKey = L23_1
L22_1.m_CutScenID = 159
L22_1.m_CutScenStrID = "EP5_ACT1_PROLOGUE"
L22_1.m_bWaitClick = true
L22_1.m_fWaitTime = 0
L22_1.m_CharStrID = "IAN_EXTRA_NULL_NULL"
L23_1 = "군사용이 분명한 보급 물자와 정체불명의 차원간 항해용 함선들이 연구소에 수시로 드나들더군."
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "間違いなく軍事用とみられる補給品や、\n次元間航海向けの正体不明の艦船が研究所に頻繁に出入りしていた。"
L22_1.m_Talk_JPN = L23_1
L23_1 = "Military supplies were being carried in and out of the lab; unidentified ships for inter-dimensional navigation were frequenting the premises."
L22_1.m_Talk_ENG = L23_1
L23_1 = "明顯是軍事用的補給物資、身份不明的次元間航行用艦船，全都頻繁地出入研究所。"
L22_1.m_Talk_TWN = L23_1
L23_1 = "มีการส่งของใช้ทางการทหารเข้าออกห้องทดลอง ยานรบสำหรับการเดินทางข้ามมิติไร้สังกัดแวะเวียนมาที่นั่นบ่อยๆ"
L22_1.m_Talk_THA = L23_1
L23_1 = "Quân nhu được mang ra mang vào phòng thí nghiệm; những con tàu không rõ danh tính để di chuyển liên chiều đã thường xuyên xuất hiện tại các cơ sở."
L22_1.m_Talk_VTN = L23_1
L23_1 = "军事用的补给物资、不明身份的航海用舰船，随时随地都在出入研究所。"
L22_1.m_Talk_SCN = L23_1
L23_1 = "Militärische Güter wurden ins Labor hinein- und wieder hinausgetragen; nicht gekennzeichnete Schiffe für interdimensionale Navigation verkehrten auf dem Gelände."
L22_1.m_Talk_DEU = L23_1
L23_1 = "Du matériel militaire allait et venait dans le laboratoire, des vaisseaux non identifiés conçus pour la navigation interdimensionnelle étaient entreposés."
L22_1.m_Talk_FRA = L23_1
L23_1 = {}
L24_1 = "EP5_ACT1_PROLOGUE@73#Talk"
L23_1.m_CutScenKey_Talk = L24_1
L24_1 = 73
L23_1.m_CutScenProcessKey = L24_1
L23_1.m_CutScenID = 159
L23_1.m_CutScenStrID = "EP5_ACT1_PROLOGUE"
L23_1.m_bWaitClick = true
L23_1.m_fWaitTime = 0
L23_1.m_CharStrID = "IAN_EXTRA_NULL_NULL"
L24_1 = "결정적으로 내가 잘못된 선택을 했다는 것을 알게 된 건......"
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "自分が間違った選択をしたと確信したのは……"
L23_1.m_Talk_JPN = L24_1
L24_1 = "More than everything, I knew that I've made a terrible decision"
L23_1.m_Talk_ENG = L24_1
L24_1 = "最後讓我發現我做出了錯誤選擇的……"
L23_1.m_Talk_TWN = L24_1
L24_1 = "และที่สำคัญที่สุด ผมรู้ตัวว่าผมตัดสินใจพลาดไปแล้ว"
L23_1.m_Talk_THA = L24_1
L24_1 = "Hơn tất cả mọi thứ, tôi biết rằng tôi đã đưa ra một quyết định tồi tệ"
L23_1.m_Talk_VTN = L24_1
L24_1 = "最终，我发现了一件不得了的事情。"
L23_1.m_Talk_SCN = L24_1
L24_1 = "Ich merkte, dass ich eine schreckliche Entscheidung getroffen hatte,"
L23_1.m_Talk_DEU = L24_1
L24_1 = "Et surtout, j'ai su que j'avais pris une horrible décision"
L23_1.m_Talk_FRA = L24_1
L24_1 = {}
L25_1 = "EP5_ACT1_PROLOGUE@74#Talk"
L24_1.m_CutScenKey_Talk = L25_1
L25_1 = 74
L24_1.m_CutScenProcessKey = L25_1
L24_1.m_CutScenID = 159
L24_1.m_CutScenStrID = "EP5_ACT1_PROLOGUE"
L24_1.m_bWaitClick = true
L24_1.m_fWaitTime = 0
L24_1.m_CharStrID = "IAN_EXTRA_NULL_NULL"
L25_1 = "놈들이 인간에 대한 실험을 하는 장면을 목격했기 때문이야."
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "奴らが人体実験をするところを目撃したからだ。"
L24_1.m_Talk_JPN = L25_1
L25_1 = "when I saw them carrying out an experiment on a live human."
L24_1.m_Talk_ENG = L25_1
L25_1 = "是我目擊了這些傢伙做人類實驗的場面。"
L24_1.m_Talk_TWN = L25_1
L25_1 = "ตอนที่ผมเห็นเขาทำการทดลองกับมนุษย์ที่ยังมีชีวิต"
L24_1.m_Talk_THA = L25_1
L25_1 = "khi tôi thấy họ thực hiện một thí nghiệm trên người sống."
L24_1.m_Talk_VTN = L25_1
L25_1 = "因为看到了这些家伙做人类实验的场面。"
L24_1.m_Talk_SCN = L25_1
L25_1 = "als ich sah, dass ein Experiment an einem lebenden Menschen durchgeführt wurde."
L24_1.m_Talk_DEU = L25_1
L25_1 = "lorsque je les ai vus conduire une expérience sur un humain vivant."
L24_1.m_Talk_FRA = L25_1
L25_1 = {}
L26_1 = "EP5_ACT1_PROLOGUE@75#Talk"
L25_1.m_CutScenKey_Talk = L26_1
L26_1 = 75
L25_1.m_CutScenProcessKey = L26_1
L25_1.m_CutScenID = 159
L25_1.m_CutScenStrID = "EP5_ACT1_PROLOGUE"
L25_1.m_bWaitClick = true
L25_1.m_fWaitTime = 0
L25_1.m_CharStrID = "IAN_EXTRA_NULL_NULL"
L26_1 = "내가 맡은 연구는 특정 신호체계를 통해 침식체의 행동을 컨트롤하는 방법에 대한 것이었는데......"
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "私は、特定の信号システムを通して侵食体の行動を\nコントロールする方法を研究していたんだが……"
L25_1.m_Talk_JPN = L26_1
L26_1 = "The research I was in charge of was about manipulating C.O.s' behavior through a particular signal system,"
L25_1.m_Talk_ENG = L26_1
L26_1 = "我負責的研究，是透過特定信號系統控制侵蝕體行為的方法……"
L25_1.m_Talk_TWN = L26_1
L26_1 = "งานวิจัยที่ผมดูแลอยู่เกี่ยวข้องกับการควบคุมพฤติกรรมของวัตถุคอร์รัปต์ผ่านระบบสัญญาณบางอย่าง"
L25_1.m_Talk_THA = L26_1
L26_1 = "Nghiên cứu mà tôi phụ trách là điều khiển hành vi của V.T.B.A.M thông qua một hệ thống tín hiệu cụ thể,"
L25_1.m_Talk_VTN = L26_1
L26_1 = "我负责的研究是：通过特定信号体系控制侵蚀体行为的内容。"
L25_1.m_Talk_SCN = L26_1
L26_1 = "Bei der Forschung, für die ich zuständig war, ging es darum, das Verhalten von C. O.s durch ein bestimmtes Signalsystem zu manipulieren."
L25_1.m_Talk_DEU = L26_1
L26_1 = "L'étude dont j'étais en charge consistait à influencer le comportement des O.C. par le biais d'un système de signaux particuliers,"
L25_1.m_Talk_FRA = L26_1
L26_1 = {}
L27_1 = "EP5_ACT1_PROLOGUE@76#Talk"
L26_1.m_CutScenKey_Talk = L27_1
L27_1 = 76
L26_1.m_CutScenProcessKey = L27_1
L26_1.m_CutScenID = 159
L26_1.m_CutScenStrID = "EP5_ACT1_PROLOGUE"
L26_1.m_bWaitClick = true
L26_1.m_fWaitTime = 0
L26_1.m_CharStrID = "IAN_EXTRA_NULL_NULL"
L27_1 = "그 핵심 회로를 인간에게 심는 장면을 우연히 보고 말았거든."
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "そのコア回路を人間に埋め込むところをたまたま見かけてしまったんだ。"
L26_1.m_Talk_JPN = L27_1
L27_1 = "and I accidentally witnessed them planting the core circuit in a human body."
L26_1.m_Talk_ENG = L27_1
L27_1 = "但我卻偶然撞見，他們將核心回路植入人體的場面。"
L26_1.m_Talk_TWN = L27_1
L27_1 = "แล้วผมก็บังเอิญได้เห็นพวกเขาฝังวงจรหลักลงไปในร่างของมนุษย์"
L26_1.m_Talk_THA = L27_1
L27_1 = "và tôi đã vô tình chứng kiến họ trồng mạch lõi vào cơ thể người."
L26_1.m_Talk_VTN = L27_1
L27_1 = "但居然看到他们将核心电路植入人类体内的场面。"
L26_1.m_Talk_SCN = L27_1
L27_1 = "Ich wurde zufällig Zeuge, wie sie den Kernschaltkreis in einen menschlichen Körper einpflanzten."
L26_1.m_Talk_DEU = L27_1
L27_1 = "et, accidentellement, je les ai vus implanter le circuit central dans un corps humain."
L26_1.m_Talk_FRA = L27_1
L27_1 = {}
L28_1 = "EP5_ACT1_PROLOGUE@77#Talk"
L27_1.m_CutScenKey_Talk = L28_1
L28_1 = 77
L27_1.m_CutScenProcessKey = L28_1
L27_1.m_CutScenID = 159
L27_1.m_CutScenStrID = "EP5_ACT1_PROLOGUE"
L27_1.m_bWaitClick = true
L27_1.m_fWaitTime = 0
L27_1.m_CharStrID = "IAN_EXTRA_NULL_NULL"
L28_1 = "정확하게 이야기하면 이면세계에서 활동할 수 있는 인간...... 침식 융합체에게 말이지."
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "正確には、裏世界で活動できる人間……侵食融合体に対してだったが。"
L27_1.m_Talk_JPN = L28_1
L28_1 = "Or, to be exact, a body of a human who's able to operate in the Counterside: the Corruption hybrider."
L27_1.m_Talk_ENG = L28_1
L28_1 = "能夠在異界活動的人類，正確來說……就是指侵蝕融合體。"
L27_1.m_Talk_TWN = L28_1
L28_1 = "หรือพูดให้ชัดๆ ก็คือ ร่างของมนุษย์ที่สามารถอยู่ในเคาน์เตอร์ไซด์ได้ นั่นคือลูกผสมคอร์รัปชั่น"
L27_1.m_Talk_THA = L28_1
L28_1 = "Hay, chính xác là, cơ thể của một con người có thể hoạt động ở Counterside: Người Lai Tạo Ăn Mòn."
L27_1.m_Talk_VTN = L28_1
L28_1 = "说白了，能够在异界活动的人类……是指侵蚀融合体。"
L27_1.m_Talk_SCN = L28_1
L28_1 = "Genauer gesagt: In einen menschlichen Körper, der auf der Counterside agieren sollte – ein Verderbnishybride."
L27_1.m_Talk_DEU = L28_1
L28_1 = "Ou, pour être plus précis, dans le corps d'un humain capable d'opérer dans le Contremonde : un hybride de corruption."
L27_1.m_Talk_FRA = L28_1
