L34_1 = "EP5_ACT1_PROLOGUE@83#Talk"
L33_1.m_CutScenKey_Talk = L34_1
L34_1 = 83
L33_1.m_CutScenProcessKey = L34_1
L33_1.m_CutScenID = 159
L33_1.m_CutScenStrID = "EP5_ACT1_PROLOGUE"
L33_1.m_bWaitClick = true
L33_1.m_fWaitTime = 0
L33_1.m_CharStrID = "IAN_EXTRA_NULL_NULL"
L34_1 = "그제서야 난 확실히 알게 됐어."
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "そこでようやく気づいたんだ。"
L33_1.m_Talk_JPN = L34_1
L34_1 = "Everything was clear."
L33_1.m_Talk_ENG = L34_1
L34_1 = "這時我才終於明白。"
L33_1.m_Talk_TWN = L34_1
L34_1 = "ทุกอย่างเป็นที่ชัดเจน"
L33_1.m_Talk_THA = L34_1
L34_1 = "Mọi thứ đã rõ ràng."
L33_1.m_Talk_VTN = L34_1
L34_1 = "直到这时我才明白。"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Da wurde mir alles klar."
L33_1.m_Talk_DEU = L34_1
L34_1 = "Tout était clair."
L33_1.m_Talk_FRA = L34_1
L34_1 = {}
L35_1 = "EP5_ACT1_PROLOGUE@84#Talk"
L34_1.m_CutScenKey_Talk = L35_1
L35_1 = 84
L34_1.m_CutScenProcessKey = L35_1
L34_1.m_CutScenID = 159
L34_1.m_CutScenStrID = "EP5_ACT1_PROLOGUE"
L34_1.m_bWaitClick = true
L34_1.m_fWaitTime = 0
L34_1.m_CharStrID = "IAN_EXTRA_NULL_NULL"
L35_1 = "리플레이서라는 건, 이면세계를 낙원으로 대체하는 게 아니라......"
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "リプレイサーというのは、裏世界を楽園に変えるものではなく……"
L34_1.m_Talk_JPN = L35_1
L35_1 = "The replacement they were talking about had nothing to do with turning the Counterside into a habitable environment."
L34_1.m_Talk_ENG = L35_1
L35_1 = "所謂的克隆集團，並不是把異界打造成樂園……"
L34_1.m_Talk_TWN = L35_1
L35_1 = "การแทนที่ที่พวกเขาพูดถึงไม่เกี่ยวข้องอะไร\nกับการเปลี่ยนเคาน์เตอร์ไซด์เป็นสภาพแวดล้อมที่อาศัยอยู่ได้"
L34_1.m_Talk_THA = L35_1
L35_1 = "Sự Nhân Bản mà họ đang nói đến không liên quan gì đến việc biến Counterside thành một môi trường mà sinh vật có thể sinh sống được."
L34_1.m_Talk_VTN = L35_1
L35_1 = "所谓克隆集团，并不是把异界打造成乐土。"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Der „Ersatz“, von dem sie sprachen, hatte nichts damit zu tun, die Counterside in eine bewohnbare Umgebung zu verwandeln."
L34_1.m_Talk_DEU = L35_1
L35_1 = "La substitution dont ils parlaient n'avait rien à voir avec le fait de changer le Contremonde en un environnement habitable."
L34_1.m_Talk_FRA = L35_1
L35_1 = {}
L36_1 = "EP5_ACT1_PROLOGUE@85#Talk"
L35_1.m_CutScenKey_Talk = L36_1
L36_1 = 85
L35_1.m_CutScenProcessKey = L36_1
L35_1.m_CutScenID = 159
L35_1.m_CutScenStrID = "EP5_ACT1_PROLOGUE"
L35_1.m_bWaitClick = true
L35_1.m_fWaitTime = 0
L35_1.m_CharStrID = "IAN_EXTRA_NULL_NULL"
L36_1 = "인간을 자기들 마음대로 부릴 수 있는 침식 융합체로 대체하는 것이라는 걸."
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "人間を好き勝手に操れる侵食融合体にするためのものだと。"
L35_1.m_Talk_JPN = L36_1
L36_1 = "It was about changing human beings into mindless Corruption hybriders."
L35_1.m_Talk_ENG = L36_1
L36_1 = "而是將人類變成可以隨便他們使喚的侵蝕融合體。"
L35_1.m_Talk_TWN = L36_1
L36_1 = "มันเป็นเรื่องของการเปลี่ยนมนุษย์ให้กลายเป็นลูกผสมคอร์รัปชั่นที่ไร้ความคิด"
L35_1.m_Talk_THA = L36_1
L36_1 = "Đó là về việc thay đổi con người thành những người lai tạo ăn mòn vô tri."
L35_1.m_Talk_VTN = L36_1
L36_1 = "而是用那些，可以随心所欲使唤的侵蚀融合体，来代替人类。"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Es ging viel mehr darum, Menschen in hirnlose Verderbnishybriden zu verwandeln."
L35_1.m_Talk_DEU = L36_1
L36_1 = "Il s'agissait de changer les êtres humains en hybrides de corruption sans âme."
L35_1.m_Talk_FRA = L36_1
L36_1 = {}
