L38_1 = "EP5_ACT1_PROLOGUE@87#Talk"
L37_1.m_CutScenKey_Talk = L38_1
L38_1 = 87
L37_1.m_CutScenProcessKey = L38_1
L37_1.m_CutScenID = 159
L37_1.m_CutScenStrID = "EP5_ACT1_PROLOGUE"
L37_1.m_bWaitClick = true
L37_1.m_fWaitTime = 0
L37_1.m_CharStrID = "JOOSHIYOON_FENRIR_NULL_NULL"
L38_1 = "과연...... 그렇게 된 거였군요."
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "なるほど……そういうことだったんですね。"
L37_1.m_Talk_JPN = L38_1
L38_1 = "So that's what happened."
L37_1.m_Talk_ENG = L38_1
L38_1 = "果然……是這樣呢。"
L37_1.m_Talk_TWN = L38_1
L38_1 = "เรื่องเป็นแบบนี้นี่เอง"
L37_1.m_Talk_THA = L38_1
L38_1 = "Vậy ra đó là những gì đã xảy ra."
L37_1.m_Talk_VTN = L38_1
L38_1 = "果然……原来是这样啊。"
L37_1.m_Talk_SCN = L38_1
L38_1 = "So war es also."
L37_1.m_Talk_DEU = L38_1
L38_1 = "Voilà donc ce qui s'est passé."
L37_1.m_Talk_FRA = L38_1
L38_1 = {}
L39_1 = "EP5_ACT1_PROLOGUE@88#Talk"
L38_1.m_CutScenKey_Talk = L39_1
L39_1 = 88
L38_1.m_CutScenProcessKey = L39_1
L38_1.m_CutScenID = 159
L38_1.m_CutScenStrID = "EP5_ACT1_PROLOGUE"
L38_1.m_bWaitClick = true
L38_1.m_fWaitTime = 0
L38_1.m_CharStrID = "IAN_EXTRA_NULL_NULL"
L39_1 = "그때부터 나는 몰래 놈들을 저지할 수단을 준비하기 시작했지."
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "それから私は、奴らを阻止する手段を密かに考え始めた。"
L38_1.m_Talk_JPN = L39_1
L39_1 = "From that moment on, I started to devise a plan to stop them."
L38_1.m_Talk_ENG = L39_1
L39_1 = "從那個時候開始，我就悄悄地開始準備要阻止這些傢伙了。"
L38_1.m_Talk_TWN = L39_1
L39_1 = "ตั้งแต่นั้นเป็นต้นมา ผมก็เริ่มวางแผนหยุดพวกเขา"
L38_1.m_Talk_THA = L39_1
L39_1 = "Từ lúc đó, tôi bắt đầu lên kế hoạch để ngăn chặn việc này."
L38_1.m_Talk_VTN = L39_1
L39_1 = "从那时起，我就开始准备悄悄地阻止这些家伙了。"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Von dem Moment an begann ich, mir einen Plan zu überlegen, um sie aufzuhalten."
L38_1.m_Talk_DEU = L39_1
L39_1 = "À partir de ce jour, j'ai commencé à élaborer un plan pour les arrêter."
L38_1.m_Talk_FRA = L39_1
L39_1 = {}
L40_1 = "EP5_ACT1_PROLOGUE@89#Talk"
L39_1.m_CutScenKey_Talk = L40_1
L40_1 = 89
L39_1.m_CutScenProcessKey = L40_1
L39_1.m_CutScenID = 159
L39_1.m_CutScenStrID = "EP5_ACT1_PROLOGUE"
L39_1.m_bWaitClick = true
L39_1.m_fWaitTime = 0
L39_1.m_CharStrID = "IAN_EXTRA_NULL_NULL"
L40_1 = "놈들에겐 여러 가지 연구 목표가 있었는데, 개중에 가장 중요하게 추진했던 건......"
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "奴らには様々な研究目標があったが、そのなかで最も力を入れていたのは……"
L39_1.m_Talk_JPN = L40_1
L40_1 = "They had several research goals, and the most important of them all was..."
L39_1.m_Talk_ENG = L40_1
L40_1 = "他們有很多研究目標，而其中最需要推進的是……"
L39_1.m_Talk_TWN = L40_1
L40_1 = "พวกเขามีเป้าหมายในการวิจัยหลายอย่าง และอันที่สำคัญที่สุดก็คือ..."
L39_1.m_Talk_THA = L40_1
L40_1 = "Họ có một số mục tiêu nghiên cứu, và mục tiêu quan trọng nhất trong đó là ..."
L39_1.m_Talk_VTN = L40_1
L40_1 = "他们有很多研究项目，其中首要推进的是……"
L39_1.m_Talk_SCN = L40_1
L40_1 = "Sie verfolgten mehrere Forschungsziele. Das Wichtigste war:"
L39_1.m_Talk_DEU = L40_1
L40_1 = "Ils avaient plusieurs objectifs de recherche, et le plus important d'entre eux était..."
L39_1.m_Talk_FRA = L40_1
L40_1 = {}
L41_1 = "EP5_ACT1_PROLOGUE@90#Talk"
L40_1.m_CutScenKey_Talk = L41_1
L41_1 = 90
L40_1.m_CutScenProcessKey = L41_1
L40_1.m_CutScenID = 159
L40_1.m_CutScenStrID = "EP5_ACT1_PROLOGUE"
L40_1.m_bWaitClick = true
L40_1.m_fWaitTime = 0
L40_1.m_CharStrID = "IAN_EXTRA_NULL_NULL"
L41_1 = "느리고 비효율적인 외과적 시술 없이도 현실세계의 인간을 대규모로 리플레이서 융합체로 만드는 방법."
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "時間もかかって効率も悪い外科施術をせずに、\n現実世界の人間を一気にリプレイサー融合体に変える方法。"
L40_1.m_Talk_JPN = L41_1
L41_1 = "mass-converting humans in Normalside into Replacer hybriders without slow, inefficient surgical operations,"
L40_1.m_Talk_ENG = L41_1
L41_1 = "不用那些又慢又沒效率的手術，就可以大量將現實世界的人變成克隆融合體的方法。"
L40_1.m_Talk_TWN = L41_1
L41_1 = "การเปลี่ยนมนุษย์ในนอร์มอลไซด์ให้กลายเป็นรีเพลสเซอร์ประเภทไฮบริเดอร์ขนานใหญ่ โดยไม่ต้องอาศัยการผ่าตัดที่ช้าและไร้ประสิทธิภาพ"
L40_1.m_Talk_THA = L41_1
L41_1 = "biến đổi hàng loạt con người ở Normalside thành người lai tạo Nhân Bản mà không cần thủ tục phẫu thuật chậm, không hiệu quả,"
L40_1.m_Talk_VTN = L41_1
L41_1 = "即使不用做那种又慢又没有效果的手术，也可以将现实世界的人大量变成克隆融合体的方法。"
L40_1.m_Talk_SCN = L41_1
L41_1 = "Massenumwandlung von Menschen der Normside in Replacer-Hybriden, aber ohne langwierige, ineffiziente chirurgische Eingriffe."
L40_1.m_Talk_DEU = L41_1
L41_1 = "la conversion en masse des humains du Vérimonde en hybrides substituts, sans interventions chirurgicales, lentes et peu efficaces ;"
L40_1.m_Talk_FRA = L41_1
L41_1 = {}
L42_1 = "EP5_ACT1_PROLOGUE@91#Talk"
L41_1.m_CutScenKey_Talk = L42_1
L42_1 = 91
L41_1.m_CutScenProcessKey = L42_1
L41_1.m_CutScenID = 159
L41_1.m_CutScenStrID = "EP5_ACT1_PROLOGUE"
L41_1.m_bWaitClick = true
L41_1.m_fWaitTime = 0
L41_1.m_CharStrID = "IAN_EXTRA_NULL_NULL"
L42_1 = "일명 <color=#ffd34c>테라사이드 프로젝트</color>였어."
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "通称<color=#ffd34c>テラサイドプロジェクト</color>。"
