L46_1 = "EP5_ACT1_PROLOGUE@95#Talk"
L45_1.m_CutScenKey_Talk = L46_1
L46_1 = 95
L45_1.m_CutScenProcessKey = L46_1
L45_1.m_CutScenID = 159
L45_1.m_CutScenStrID = "EP5_ACT1_PROLOGUE"
L45_1.m_bWaitClick = true
L45_1.m_fWaitTime = 0
L45_1.m_CharStrID = "IAN_EXTRA_NULL_NULL"
L46_1 = "이 시스템을 완성하기 위해서는 불멸체 코어라는 구 관리국의 유물이 필수적이지."
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "このシステムを完成させるためには、不滅体コアという旧管理局の遺物が必要不可欠だった。"
L45_1.m_Talk_JPN = L46_1
L46_1 = "And this project is just unviable without an artifact of the Old Administration called the Immortal System Core."
L45_1.m_Talk_ENG = L46_1
L46_1 = "為了完成這個系統，某個叫做不滅者核心的舊管理局遺物是不可或缺的。"
L45_1.m_Talk_TWN = L46_1
L46_1 = "และโครงการนี้ก็จะเป็นไปไม่ได้ถ้าขาดอาร์ติแฟ็กต์\nขององค์การบริหารโลกในอดีตที่เรียกว่าแกนระบบอิมมอร์ทอล"
L45_1.m_Talk_THA = L46_1
L46_1 = "Và dự án này sẽ không thể thực hiện được nếu không có di tích của Cục Quản Lý Cũ được gọi là Lõi Hệ Thống Bất Diệt."
L45_1.m_Talk_VTN = L46_1
L46_1 = "为了使该系统成型，旧管理局的遗物“不灭者核心”是必不可少的。"
L45_1.m_Talk_SCN = L46_1
L46_1 = "Und dieses Projekt ist ohne ein Artefakt der Alten Administration, den Kern der Unsterblichkeitsmatrix, einfach nicht durchführbar."
L45_1.m_Talk_DEU = L46_1
L46_1 = "Et ce projet n'est pas viable sans le noyau du système immortel, un artefact datant de l'Ancienne Administration."
L45_1.m_Talk_FRA = L46_1
L46_1 = {}
L47_1 = "EP5_ACT1_PROLOGUE@96#Talk"
L46_1.m_CutScenKey_Talk = L47_1
L47_1 = 96
L46_1.m_CutScenProcessKey = L47_1
L46_1.m_CutScenID = 159
L46_1.m_CutScenStrID = "EP5_ACT1_PROLOGUE"
L46_1.m_bWaitClick = true
L46_1.m_fWaitTime = 0
L46_1.m_CharStrID = "IAN_EXTRA_NULL_NULL"
L47_1 = "하지만 불멸체 코어를 작동시키려면 특수 인자로 만들어진 대량의 에너지원과 구 관리국의 시스템 통제용 코드 체계 해독이 필요해."
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "だが、不滅体コアを作動させるには、特殊ファクターで作られた大量のエネルギー源とともに、\n旧管理局でのシステム統制用のコード体系を解読する必要がある。"
L46_1.m_Talk_JPN = L47_1
L47_1 = "To activate this Core, they need two things. One is a special factor that can generate massive energy, and the other is a code that can control the Old Administration system."
L46_1.m_Talk_ENG = L47_1
L47_1 = "但如果想要啟動不滅者核心，需要用特殊因子製造的大量能源，以及舊管理局的控制系統代碼體系化。"
L46_1.m_Talk_TWN = L47_1
L47_1 = "ในการเปิดใช้แกนนี้ พวกเขาต้องมีสองสิ่ง หนึ่งคือปัจจัยพิเศษที่สร้างพลังงานมหาศาลได้ สองคือรหัสที่ใช้ควบคุมระบบองค์การบริหารโลกในอดีตได้"
L46_1.m_Talk_THA = L47_1
L47_1 = "Cần hai thứ để kích hoạt Lõi này. Một là thông số đặc biệt có thể tạo ra một lượng năng lượng lớn, và thứ còn lại là mã có thể điều khiển hệ thống Cục Quản Lý Cũ."
L46_1.m_Talk_VTN = L47_1
L47_1 = "但如果要想启动不灭者核心，还需要特殊因子制造的大量能源，以及旧管理局的系统控制用代码系统，来进行破解。"
L46_1.m_Talk_SCN = L47_1
L47_1 = "Um diesen Kern zu aktivieren, braucht man zwei Dinge: einen speziellen Faktor, der enorme Energie erzeugen kann, und einen Code, der das System der Alten Administration steuern kann."
L46_1.m_Talk_DEU = L47_1
L47_1 = "Ils ont besoin de deux choses pour activer ce noyau. Premièrement d'un dispositif particulier capable de générer une quantité massive d'énergie, et deuxièmement d'un code qui permet de contrôler le système de l'Ancienne Administration."
L46_1.m_Talk_FRA = L47_1
L47_1 = {}
L48_1 = "EP5_ACT1_PROLOGUE@97#Talk"
L47_1.m_CutScenKey_Talk = L48_1
L48_1 = 97
L47_1.m_CutScenProcessKey = L48_1
L47_1.m_CutScenID = 159
L47_1.m_CutScenStrID = "EP5_ACT1_PROLOGUE"
L47_1.m_bWaitClick = true
L47_1.m_fWaitTime = 0
L47_1.m_CharStrID = "IAN_EXTRA_NULL_NULL"
L48_1 = "다행히 아직까지는 이 두 가지 요소를 충족시키지 못했지만......"
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "幸いなことに、この二つの条件はまだ満たしていないが……"
L47_1.m_Talk_JPN = L48_1
L48_1 = "Fortunately, they have been clueless as to how they could possibly work this out."
L47_1.m_Talk_ENG = L48_1
L48_1 = "慶幸的是，到目前為止，他們還沒能達成這兩個要素。"
L47_1.m_Talk_TWN = L48_1
L48_1 = "โชคดีที่พวกนั้นไม่รู้เลยว่าจะทำได้ยังไง"
L47_1.m_Talk_THA = L48_1
L48_1 = "May mắn thay, bọn chúng không biết cách giải quyết những chuyện này."
L47_1.m_Talk_VTN = L48_1
L48_1 = "好在，目前为止，现有条件还没能满足这两个因素。"
L47_1.m_Talk_SCN = L48_1
L48_1 = "Glücklicherweise wussten sie nicht, wie sie das bewerkstelligen sollten."
L47_1.m_Talk_DEU = L48_1
L48_1 = "Fort heureusement, ils n'avaient jamais réussi à comprendre comment faire fonctionner tout ça."
L47_1.m_Talk_FRA = L48_1
L48_1 = {}
L49_1 = "EP5_ACT1_PROLOGUE@98#Talk"
L48_1.m_CutScenKey_Talk = L49_1
L49_1 = 98
L48_1.m_CutScenProcessKey = L49_1
L48_1.m_CutScenID = 159
L48_1.m_CutScenStrID = "EP5_ACT1_PROLOGUE"
L48_1.m_bWaitClick = true
L48_1.m_fWaitTime = 0
L48_1.m_CharStrID = "IAN_EXTRA_NULL_NULL"
L49_1 = "최근에 우리에게 접근해 온 육익이라는 단체에서 그 문제를 해결할 방법을 가지고 있다고 하더군."
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "最近我々に近づいてきた六翼という団体が、その問題の解決方法を有しているという。"
L48_1.m_Talk_JPN = L49_1
L49_1 = "However, an organization named Six Wings recently contacted us and said they'd take care of it."
L48_1.m_Talk_ENG = L49_1
L49_1 = "但最近，一個叫“六翼”的團體向我們接觸，並說他們有辦法解決這個問題。"
L48_1.m_Talk_TWN = L49_1
L49_1 = "แต่องค์กรที่ชื่อซิกส์วิงส์เพิ่งติดต่อเราเมื่อเร็วๆ นี้ และบอกว่าพวกเขาจะจัดการให้"
L48_1.m_Talk_THA = L49_1
L49_1 = "Tuy nhiên, một tổ chức có tên Six Wings gần đây đã liên hệ với chúng tôi và nói rằng họ sẽ xử lý việc đó."
L48_1.m_Talk_VTN = L49_1
L49_1 = "但最近，我们接触到一个叫“六翼”的团队竟然说：他们有办法解决这个问题。"
L48_1.m_Talk_SCN = L49_1
L49_1 = "Unlängst meldete sich jedoch eine Organisation namens „Sechs Schwingen“ und sagte zu, dass sie sich darum kümmern würde."
L48_1.m_Talk_DEU = L49_1
L49_1 = "Mais une organisation baptisée Six Ailes nous a contactés récemment pour nous proposer de s'en occuper."
L48_1.m_Talk_FRA = L49_1
L49_1 = {}
L50_1 = "EP5_ACT1_PROLOGUE@99#Talk"
L49_1.m_CutScenKey_Talk = L50_1
L50_1 = 99
L49_1.m_CutScenProcessKey = L50_1
L49_1.m_CutScenID = 159
L49_1.m_CutScenStrID = "EP5_ACT1_PROLOGUE"
L49_1.m_bWaitClick = true
L49_1.m_fWaitTime = 0
L49_1.m_CharStrID = "IAN_EXTRA_NULL_NULL"
L50_1 = "물론 당장은 아니고 상당한 기간의 준비작업이 필요하다고는 하지만......"
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "もちろん今すぐではなく、相当な準備期間が必要とは言われているが……"
L49_1.m_Talk_JPN = L50_1
L50_1 = "They say they need time for preparation,"
L49_1.m_Talk_ENG = L50_1
L50_1 = "當然不是立刻，需要相當長期的準備作業。"
L49_1.m_Talk_TWN = L50_1
L50_1 = "พวกเขาบอกว่าต้องการเวลาสำหรับเตรียมการ"
L49_1.m_Talk_THA = L50_1
L50_1 = "Họ nói rằng họ cần thời gian để chuẩn bị,"
L49_1.m_Talk_VTN = L50_1
L50_1 = "虽然现在无法立即实现，需要比较长的一段时间来进行准备的工作。"
L49_1.m_Talk_SCN = L50_1
L50_1 = "Sie sagen, sie bräuchten Zeit für die Vorbereitung."
L49_1.m_Talk_DEU = L50_1
L50_1 = "Ils ont dit qu'ils avaient besoin de temps pour se préparer,"
L49_1.m_Talk_FRA = L50_1
L50_1 = {}
L51_1 = "EP5_ACT1_PROLOGUE@100#Talk"
L50_1.m_CutScenKey_Talk = L51_1
L51_1 = 100
L50_1.m_CutScenProcessKey = L51_1
L50_1.m_CutScenID = 159
L50_1.m_CutScenStrID = "EP5_ACT1_PROLOGUE"
L50_1.m_bWaitClick = true
L50_1.m_fWaitTime = 0
L50_1.m_CharStrID = "IAN_EXTRA_NULL_NULL"
L51_1 = "결국 언젠가는 목표를 달성하게 될 거야."
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "いつかはきっと目標を達成するだろう。"
L50_1.m_Talk_JPN = L51_1
L51_1 = "but it won't be long before they finally do it."
L50_1.m_Talk_ENG = L51_1
L51_1 = "但最終，他們總有一天會達成目標的。"
L50_1.m_Talk_TWN = L51_1
L51_1 = "แต่อีกไม่นานพวกเขาก็จะลงมือ"
L50_1.m_Talk_THA = L51_1
L51_1 = "nhưng sẽ không còn lâu nữa trước khi cuối cùng họ làm đó."
L50_1.m_Talk_VTN = L51_1
L51_1 = "但他们总有一天会达到目的的。"
L50_1.m_Talk_SCN = L51_1
L51_1 = "Aber es wird nicht mehr lange dauern, bis sie loslegen."
L50_1.m_Talk_DEU = L51_1
L51_1 = "mais qu'ils y parviendront très prochainement."
L50_1.m_Talk_FRA = L51_1
