L3_1 = "EP5_ACT1_PROLOGUE@102#Talk"
L2_1.m_CutScenKey_Talk = L3_1
L3_1 = 102
L2_1.m_CutScenProcessKey = L3_1
L2_1.m_CutScenID = 159
L2_1.m_CutScenStrID = "EP5_ACT1_PROLOGUE"
L2_1.m_bWaitClick = true
L2_1.m_fWaitTime = 0
L2_1.m_CharStrID = "IAN_EXTRA_NULL_NULL"
L3_1 = "나는 오늘 밤에 불멸체 코어를 탈취하여 파괴할 계획이다."
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "私は今晩、不滅体コアを奪って破壊するつもりだ。"
L2_1.m_Talk_JPN = L3_1
L3_1 = "I'm going to steal the Immortal System Core tonight and destroy it."
L2_1.m_Talk_ENG = L3_1
L3_1 = "我今晚計畫去奪取並破壞掉不滅者核心。"
L2_1.m_Talk_TWN = L3_1
L3_1 = "ผมจะขโมยแกนระบบอิมมอร์ทอลคืนนี้แล้วทำลายมันซะ"
L2_1.m_Talk_THA = L3_1
