L10_1.m_CharStrID = "IAN_EXTRA_NULL_NULL"
L11_1 = "뭐, 이 비디오를 보고 있는 시점에서 난 실패했거나 죽었다는 뜻이겠군."
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "まあ、この動画を見てる時点で、私は失敗してるか命を落としてるということになるな。"
L10_1.m_Talk_JPN = L11_1
L11_1 = "Well, if you're watching this, you'll have to consider that I failed or died trying."
L10_1.m_Talk_ENG = L11_1
L11_1 = "不，當你們看到這個影片時，就代表我已經失敗，或是死了吧。"
L10_1.m_Talk_TWN = L11_1
L11_1 = "ถ้าคุณกำลังดูวิดีโอนี้อยู่ คุณคงรู้ว่าผมทำพลาดหรือพยายามจนตัวตาย"
L10_1.m_Talk_THA = L11_1
L11_1 = "Chà, nếu bạn đang xem cái này, bạn sẽ phải cân nhắc rằng tôi có thể sẽ thất bại hoặc chết khi cố gắng làm điều đó."
L10_1.m_Talk_VTN = L11_1
L11_1 = "呼，你们看到这盘录像带的时候，就意味着我失败了或者已经死了。"
L10_1.m_Talk_SCN = L11_1
L11_1 = "Na ja, wenn du das hier siehst, kannst du davon ausgehen, dass ich bei dem Versuch gescheitert oder ums Leben gekommen bin."
L10_1.m_Talk_DEU = L11_1
L11_1 = "Disons que si vous regardez ça, vous devez considérer que j'ai échoué ou que je suis mort en essayant."
L10_1.m_Talk_FRA = L11_1
L11_1 = {}
L12_1 = "EP5_ACT1_PROLOGUE@111#Talk"
L11_1.m_CutScenKey_Talk = L12_1
L12_1 = 111
L11_1.m_CutScenProcessKey = L12_1
L11_1.m_CutScenID = 159
