L11_1.m_CharStrID = "IAN_EXTRA_NULL_NULL"
L12_1 = "하지만 너무 걱정하지는 말라고."
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "だが、あまり案じることはない。"
L11_1.m_Talk_JPN = L12_1
L12_1 = "But don't you worry too much."
L11_1.m_Talk_ENG = L12_1
L12_1 = "不過不需要太擔心。"
L11_1.m_Talk_TWN = L12_1
L12_1 = "แต่ไม่ต้องกังวลมากจนเกินไปนะ"
L11_1.m_Talk_THA = L12_1
L12_1 = "Nhưng bạn cũng đừng quá lo lắng."
L11_1.m_Talk_VTN = L12_1
L12_1 = "但，你们不要太担心哦。"
L11_1.m_Talk_SCN = L12_1
L12_1 = "Aber sei nicht zu bedrückt!"
