L13_1 = "EP5_ACT1_PROLOGUE@112#Talk"
L12_1.m_CutScenKey_Talk = L13_1
L13_1 = 112
L12_1.m_CutScenProcessKey = L13_1
L12_1.m_CutScenID = 159
L12_1.m_CutScenStrID = "EP5_ACT1_PROLOGUE"
L12_1.m_bWaitClick = true
L12_1.m_fWaitTime = 0
L12_1.m_CharStrID = "IAN_EXTRA_NULL_NULL"
L13_1 = "플랜 B는 언제나 준비되어 있으니까."
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "プランBは常に用意してあるからな。"
L12_1.m_Talk_JPN = L13_1
L13_1 = "I never do anything without a Plan B."
L12_1.m_Talk_ENG = L13_1
L13_1 = "因為我隨時都會準備Ｂ計畫。"
L12_1.m_Talk_TWN = L13_1
L13_1 = "ผมไม่เคยทำอะไรโดยไม่มีแผนสอง"
L12_1.m_Talk_THA = L13_1
L13_1 = "Tôi không bao giờ làm bất cứ điều gì mà không có kế hoạch B."
L12_1.m_Talk_VTN = L13_1
L13_1 = "因为PLAN B 随时都准备着。"
L12_1.m_Talk_SCN = L13_1
L13_1 = "Denn ich mache nie etwas ohne einen Plan B."
L12_1.m_Talk_DEU = L13_1
L13_1 = "Je ne fais jamais rien sans un plan B."
