L14_1 = "EP5_ACT1_PROLOGUE@113#Talk"
L13_1.m_CutScenKey_Talk = L14_1
L14_1 = 113
L13_1.m_CutScenProcessKey = L14_1
L13_1.m_CutScenID = 159
L13_1.m_CutScenStrID = "EP5_ACT1_PROLOGUE"
L13_1.m_bWaitClick = true
L13_1.m_fWaitTime = 0
L13_1.m_CharStrID = "IAN_EXTRA_NULL_NULL"
L14_1 = "자세한 내용은 역탐지를 피하기 위해 세 개의 더미데이터로 나누어 각각 내 동료인 제인 도우의 개인 메일 계정과 리플레이서의 VPN 네트워크......"
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "詳しい内容は逆探知を避けるために3つのダミーデータに分けて、\nそれぞれ仲間のジェーン・ドウの個人メールアカウントやリプレイサーのVPNネットワーク、"
L13_1.m_Talk_JPN = L14_1
L14_1 = "I've divided the plan into three sets of dummy data and placed one in my colleague Jane Doe's personal mail account, another one in the VPN network of the Replacers,"
L13_1.m_Talk_ENG = L14_1
L14_1 = "至於詳細內容，為了避免逆向搜索，我把內容分成了三組虛擬數據，分別透過我的同事，珍妮．多伊的個人信箱和克隆集團的VPN網路……"
L13_1.m_Talk_TWN = L14_1
L14_1 = "ผมแบ่งแผนออกเป็นข้อมูลปลอมสามชุด ผมใส่ข้อมูลชุดหนึ่งไว้ในบัญชีเมลส่วนตัวของเจน โด เพื่อนร่วมงานของผม อีกชุดอยู่ในเครือข่าย VPN ของรีเพลสเซอร์"
L13_1.m_Talk_THA = L14_1
L14_1 = "Tôi đã chia kế hoạch thành ba bộ dữ liệu giả và đặt một bộ vào tài khoản thư cá nhân của đồng nghiệp của tôi, Jane Doe, một bộ khác trong mạng VPN của Người Nhân Bản,"
L13_1.m_Talk_VTN = L14_1
L14_1 = "详细来说：为了躲开电波的探测，我把内容分成了三组，分别储存在我的同事：简的个人邮件账户、克隆集团的VPN网络……"
L13_1.m_Talk_SCN = L14_1
L14_1 = "Ich habe diesen Plan in drei Sätze von Schein-Daten aufgeteilt – einen habe ich im persönlichen E-Mail-Konto meiner Kollegin Jane Doe platziert, einen weiteren im VPN-Netzwerk der Replacer,"
L13_1.m_Talk_DEU = L14_1
L14_1 = "J'ai divisé le plan en trois groupes de données factices et j'en ai placé un dans le compte de messagerie personnel de ma collègue Jane Doe, un autre dans le réseau VPN des substituts,"
L13_1.m_Talk_FRA = L14_1
L14_1 = {}
L15_1 = "EP5_ACT1_PROLOGUE@114#Talk"
L14_1.m_CutScenKey_Talk = L15_1
L15_1 = 114
L14_1.m_CutScenProcessKey = L15_1
L14_1.m_CutScenID = 159
L14_1.m_CutScenStrID = "EP5_ACT1_PROLOGUE"
L14_1.m_bWaitClick = true
L14_1.m_fWaitTime = 0
L14_1.m_CharStrID = "IAN_EXTRA_NULL_NULL"
L15_1 = "그리고 어떤 간부 후보생의 몸에 탑재된 베리칩에 저장해 놓았다."
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "そしてある幹部候補生の身体に埋め込まれたベリーチップに保存しておいた。"
L14_1.m_Talk_JPN = L15_1
L15_1 = "and the last one on the VeriChip planted in one of the officer candidates."
L14_1.m_Talk_ENG = L15_1
L15_1 = "以及儲存在某個幹部候補生身上裝載的超級晶片裡。"
L14_1.m_Talk_TWN = L15_1
L15_1 = "และชุดสุดท้ายอยู่ใน VeriChip ที่ฝังไว้ในอาสาสมัครเจ้าหน้าที่คนหนึ่ง"
L14_1.m_Talk_THA = L15_1
L15_1 = "và bộ cuối cùng trên VeriChip được cấy vào một trong các ứng viên nhân viên."
L14_1.m_Talk_VTN = L15_1
L15_1 = "还有某头目候补生身上装载的超级芯片里。"
L14_1.m_Talk_SCN = L15_1
L15_1 = "und den dritten auf dem VeriChip, der einem der Offiziersanwärter eingepflanzt wurde."
L14_1.m_Talk_DEU = L15_1
L15_1 = "et le dernier dans la VériPuce implantée dans l'une des candidates officiers."
L14_1.m_Talk_FRA = L15_1
L15_1 = {}
L16_1 = "EP5_ACT1_PROLOGUE@115#Talk"
L15_1.m_CutScenKey_Talk = L16_1
L16_1 = 115
L15_1.m_CutScenProcessKey = L16_1
L15_1.m_CutScenID = 159
L15_1.m_CutScenStrID = "EP5_ACT1_PROLOGUE"
L15_1.m_bWaitClick = true
L15_1.m_fWaitTime = 0
L15_1.m_CharStrID = "IAN_EXTRA_NULL_NULL"
L16_1 = "모르는 사람이 본다면 그저 쓰레기 데이터일 뿐이겠지만, 셋을 합치면......"
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "事情を知らない人から見ればただのゴミデータだろうが、その三つを合わせれば……"
L15_1.m_Talk_JPN = L16_1
L16_1 = "They'd look like meaningless trash data to those who aren't in the know,"
L15_1.m_Talk_ENG = L16_1
L16_1 = "不知情的人看到了，大概只會以為是些垃圾資料，但要是這三個合起來的話……"
L15_1.m_Talk_TWN = L16_1
L16_1 = "พวกมันจะดูเหมือนข้อมูลขยะที่ไร้ความหมายสำหรับคนที่ไม่รู้"
L15_1.m_Talk_THA = L16_1
L16_1 = "Chúng trông giống như dữ liệu rác vô nghĩa đối với những người không biết gì,"
L15_1.m_Talk_VTN = L16_1
L16_1 = "如果不知情的人看到，只会以为是无用的垃圾数据，但是这三者加起来的话……"
L15_1.m_Talk_SCN = L16_1
L16_1 = "Für alle, die sich nicht auskennen, sieht es aus wie bedeutungsloser Datenmüll."
L15_1.m_Talk_DEU = L16_1
L16_1 = "Ces données ont l'air inutiles lorsqu'on ne sait pas ce qu'on recherche,"
L15_1.m_Talk_FRA = L16_1
L16_1 = {}
L17_1 = "EP5_ACT1_PROLOGUE@116#Talk"
L16_1.m_CutScenKey_Talk = L17_1
L17_1 = 116
L16_1.m_CutScenProcessKey = L17_1
L16_1.m_CutScenID = 159
L16_1.m_CutScenStrID = "EP5_ACT1_PROLOGUE"
L16_1.m_bWaitClick = true
L16_1.m_fWaitTime = 0
L16_1.m_CharStrID = "IAN_EXTRA_NULL_NULL"
L17_1 = "적어도 놈들을 막을 수 있는 한 번의 기회 정도는 만들어 줄 거다."
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "少なくとも奴らを阻止するチャンスを、一回くらいは作ってくれるだろう。"
L16_1.m_Talk_JPN = L17_1
L17_1 = "but if you combine all three of them, it'd give you a chance to strike back."
L16_1.m_Talk_ENG = L17_1
L17_1 = "至少能創造一個可以阻止這些傢伙的機會。"
L16_1.m_Talk_TWN = L17_1
L17_1 = "แต่ถ้าเอาข้อมูลทั้งสามมารวมกัน มันจะทำให้เรามีโอกาสโต้กลับ"
L16_1.m_Talk_THA = L17_1
L17_1 = "nhưng nếu bạn kết hợp cả ba bộ, nó sẽ đem lại cho bạn cơ hội phản công."
L16_1.m_Talk_VTN = L17_1
L17_1 = "至少能创造一个可以阻止这些家伙的机会。"
L16_1.m_Talk_SCN = L17_1
L17_1 = "Aber wenn man alle drei Datensätze kombiniert, hat man die Chance, zurückzuschlagen."
L16_1.m_Talk_DEU = L17_1
L17_1 = "mais si vous les combinez toutes les trois, elles vous donneront une chance de riposter."
L16_1.m_Talk_FRA = L17_1
L17_1 = {}
L18_1 = "EP5_ACT1_PROLOGUE@117#Talk"
L17_1.m_CutScenKey_Talk = L18_1
L18_1 = 117
L17_1.m_CutScenProcessKey = L18_1
L17_1.m_CutScenID = 159
L17_1.m_CutScenStrID = "EP5_ACT1_PROLOGUE"
L17_1.m_bWaitClick = true
L17_1.m_fWaitTime = 0
L17_1.m_CharStrID = "IAN_EXTRA_NULL_NULL"
L18_1 = "속죄...... 라고는 할 수 없겠지만......"
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "罪滅ぼし……とまでは言えないだろうが……"
L17_1.m_Talk_JPN = L18_1
L18_1 = "I wouldn't say I'm doing this to expiate my sins,"
L17_1.m_Talk_ENG = L18_1
L18_1 = "贖罪……應該不能這麼說吧……"
L17_1.m_Talk_TWN = L18_1
L18_1 = "ผมจะไม่บอกว่าผมทำแบบนี้เพื่อล้างบาปให้ตัวเองนะ"
L17_1.m_Talk_THA = L18_1
L18_1 = "Tôi sẽ không nói rằng tôi làm điều này để bù đắp tội lỗi của mình,"
L17_1.m_Talk_VTN = L18_1
L18_1 = "虽然不知道能不能当作赎罪……"
L17_1.m_Talk_SCN = L18_1
L18_1 = "Ich will nicht behaupten, dass ich das tue, um mich von meinen Sünden reinzuwaschen …"
L17_1.m_Talk_DEU = L18_1
L18_1 = "Je n'irai pas jusqu'à dire que je fais ça pour expier mes péchés,"
L17_1.m_Talk_FRA = L18_1
L18_1 = {}
L19_1 = "EP5_ACT1_PROLOGUE@118#Talk"
L18_1.m_CutScenKey_Talk = L19_1
L19_1 = 118
L18_1.m_CutScenProcessKey = L19_1
L18_1.m_CutScenID = 159
L18_1.m_CutScenStrID = "EP5_ACT1_PROLOGUE"
L18_1.m_bWaitClick = true
L18_1.m_fWaitTime = 0
L18_1.m_CharStrID = "IAN_EXTRA_NULL_NULL"
L19_1 = "이 저주받을 계획을 도운 사람으로서, 최소한의 책임을 지는 거라고 생각해 주면 좋겠어."
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "この呪われた計画に加担した者として、最低限の責任をとるものだと考えてほしい。"
L18_1.m_Talk_JPN = L19_1
L19_1 = "but I'd be glad if you could think of this as my way of taking responsibility."
L18_1.m_Talk_ENG = L19_1
L19_1 = "但作為一個曾經協助過這個受詛咒計畫的人，我想要負起最起碼的責任。"
L18_1.m_Talk_TWN = L19_1
L19_1 = "แต่ผมจะดีใจ หากคุณมองว่านี่คือวิธีแสดงความรับผิดชอบของผม"
L18_1.m_Talk_THA = L19_1
L19_1 = "nhưng tôi rất vui nếu bạn có thể coi đây là cách tôi hoàn thành trách nhiệm của mình."
L18_1.m_Talk_VTN = L19_1
L19_1 = "但我作为一个曾经参与过这个不详计划的人来说，负起最起码的责任也是好的。"
L18_1.m_Talk_SCN = L19_1
L19_1 = "Aber ich würde mich freuen, wenn du es als meine Art betrachten könntest, Verantwortung zu übernehmen."
L18_1.m_Talk_DEU = L19_1
L19_1 = "mais je serais heureux si vous pouviez le voir comme ma façon d'assumer mes responsabilités."
L18_1.m_Talk_FRA = L19_1
L19_1 = {}
L20_1 = "EP5_ACT1_PROLOGUE@119#Talk"
L19_1.m_CutScenKey_Talk = L20_1
L20_1 = 119
L19_1.m_CutScenProcessKey = L20_1
L19_1.m_CutScenID = 159
L19_1.m_CutScenStrID = "EP5_ACT1_PROLOGUE"
L19_1.m_bWaitClick = true
L19_1.m_fWaitTime = 0
L19_1.m_CharStrID = "IAN_EXTRA_NULL_NULL"
L20_1 = "그럼 잘 부탁하지, 시청자 여러분."
L19_1.m_Talk_KOREA = L20_1
L19_1.m_fTalkTime = 0.03
L20_1 = "それではよろしく頼むぞ、ご覧の皆さん。"
L19_1.m_Talk_JPN = L20_1
L20_1 = "Then, whoever's watching, I bid you farewell."
L19_1.m_Talk_ENG = L20_1
L20_1 = "那就拜託你們了，看到這段影像的朋友們。"
L19_1.m_Talk_TWN = L20_1
L20_1 = "ถ้างั้น ใครก็ตามที่ดูอยู่ ผมขอลาก่อน"
L19_1.m_Talk_THA = L20_1
L20_1 = "Vậy nên, dù ai đang xem, tôi cũng xin tạm biệt."
L19_1.m_Talk_VTN = L20_1
L20_1 = "那就拜托了，在听的这段录音的朋友们。"
L19_1.m_Talk_SCN = L20_1
L20_1 = "Nun, wer auch immer zuschaut, ich verabschiede mich."
L19_1.m_Talk_DEU = L20_1
L20_1 = "Il ne me reste plus qu'à vous faire mes adieux, qui que vous soyez."
L19_1.m_Talk_FRA = L20_1
L20_1 = {}
L21_1 = "EP5_ACT1_PROLOGUE@120#Talk"
L20_1.m_CutScenKey_Talk = L21_1
L21_1 = 120
L20_1.m_CutScenProcessKey = L21_1
L20_1.m_CutScenID = 159
L20_1.m_CutScenStrID = "EP5_ACT1_PROLOGUE"
L20_1.m_bWaitClick = true
L20_1.m_fWaitTime = 0
L20_1.m_CharStrID = "IAN_EXTRA_NULL_NULL"
L21_1 = "꼭 세상을 지켜내기 바란다."
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "必ず、この世界を守り抜いてくれ。"
L20_1.m_Talk_JPN = L21_1
L21_1 = "I hope you'll be able to save the world."
L20_1.m_Talk_ENG = L21_1
L21_1 = "請你們一定要守護世界。"
L20_1.m_Talk_TWN = L21_1
L21_1 = "หวังว่าคุณจะช่วยโลกเอาไว้ได้"
L20_1.m_Talk_THA = L21_1
L21_1 = "Tôi hy vọng bạn sẽ có thể cứu thế giới."
L20_1.m_Talk_VTN = L21_1
L21_1 = "请你们，一定要守护世界。"
L20_1.m_Talk_SCN = L21_1
L21_1 = "Ich hoffe, du kannst die Welt retten."
L20_1.m_Talk_DEU = L21_1
L21_1 = "J'espère que vous pourrez sauver le monde."
L20_1.m_Talk_FRA = L21_1
L21_1 = {}
