L23_1 = "EP5_ACT1_PROLOGUE@122#Talk"
L22_1.m_CutScenKey_Talk = L23_1
L23_1 = 122
L22_1.m_CutScenProcessKey = L23_1
L22_1.m_CutScenID = 159
L22_1.m_CutScenStrID = "EP5_ACT1_PROLOGUE"
L22_1.m_bWaitClick = true
L22_1.m_fWaitTime = 0
L22_1.m_CharStrID = "IAN_EXTRA_NULL_NULL"
L23_1 = "아, 그리고 혹시라도...... 내 동생을 만난다면......"
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "あ、それから、もしも……私の弟に会ったら……"
L22_1.m_Talk_JPN = L23_1
L23_1 = "And oh, by the way... if you ever do come across my brother..."
L22_1.m_Talk_ENG = L23_1
L23_1 = "啊，對了……如果你們遇到我弟弟的話……"
L22_1.m_Talk_TWN = L23_1
L23_1 = "เอ้อ จะว่าไป... ถ้าคุณได้พบน้องชายของผม..."
L22_1.m_Talk_THA = L23_1
L23_1 = "Và ồ, nhân tiện ... nếu bạn tình cờ gặp anh trai tôi ..."
L22_1.m_Talk_VTN = L23_1
L23_1 = "还有……如果你们遇到我弟弟的话……"
L22_1.m_Talk_SCN = L23_1
L23_1 = "Und übrigens, falls du je meinen Bruder treffen solltest …"
L22_1.m_Talk_DEU = L23_1
L23_1 = "Oh, et sinon... si par hasard vous croisez mon frère..."
L22_1.m_Talk_FRA = L23_1
L23_1 = {}
L24_1 = "EP5_ACT1_PROLOGUE@123#Talk"
L23_1.m_CutScenKey_Talk = L24_1
L24_1 = 123
L23_1.m_CutScenProcessKey = L24_1
L23_1.m_CutScenID = 159
L23_1.m_CutScenStrID = "EP5_ACT1_PROLOGUE"
L23_1.m_bWaitClick = true
L23_1.m_fWaitTime = 0
L23_1.m_CharStrID = "IAN_EXTRA_NULL_NULL"
L24_1 = "같이 사업하자는 놈들은 다 사기꾼이니까, 형처럼 바보 같은 보이스 피싱에 낚이지 말라고 전해 주면 좋겠군."
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "一緒に起業しようと誘ってくる奴なんか全員詐欺師に決まってるから、\n兄のようにバカみたいな手口に騙されるなと伝えてくれ。"
L23_1.m_Talk_JPN = L24_1
L24_1 = "Please tell him that all the bigmouths that want to get into business with him are liars, and not to get scammed like his stupid brother."
L23_1.m_Talk_ENG = L24_1
L24_1 = "請幫我轉告他，說要一起做大事業的人都是騙子，不要像哥哥這種蠢蛋一樣上當了。"
L23_1.m_Talk_TWN = L24_1
L24_1 = "ฝากบอกเขาทีว่าพวกปากมากที่อยากร่วมงานกับเขาเป็นพวกโกหก และอย่าถูกหลอกเหมือนพี่ชายโง่ๆ ของตัวเองล่ะ"
L23_1.m_Talk_THA = L24_1
L24_1 = "Xin hãy nói với anh ấy rằng tất cả những kẻ lớn tiếng nói muốn làm ăn với anh ấy đều là những kẻ dối trá, và đừng để bị lừa như người em ngốc ngếch của anh ấy."
L23_1.m_Talk_VTN = L24_1
L24_1 = "请你帮我转告他，说要一起搞大事业的人，其实都是骗子。不要像哥哥一样被骗了。"
L23_1.m_Talk_SCN = L24_1
L24_1 = "Bitte sag ihm, dass all die Großmäuler, die mit ihm ins Geschäft kommen wollen, Lügner sind – und dass er sich nicht übers Ohr hauen lassen soll, wie sein dummer Bruder."
L23_1.m_Talk_DEU = L24_1
L24_1 = "Dites-lui que tous les beaux parleurs qui veulent faire des affaires avec lui sont des menteurs, et qu'il ne doit pas se faire arnaquer comme son idiot de frère."
L23_1.m_Talk_FRA = L24_1
L24_1 = {}
L25_1 = "EP5_ACT1_PROLOGUE@124#Talk"
L24_1.m_CutScenKey_Talk = L25_1
L25_1 = 124
L24_1.m_CutScenProcessKey = L25_1
L24_1.m_CutScenID = 159
L24_1.m_CutScenStrID = "EP5_ACT1_PROLOGUE"
L24_1.m_bWaitClick = true
L24_1.m_fWaitTime = 0
L24_1.m_CharStrID = "IAN_EXTRA_NULL_NULL"
L25_1 = "그리고 사랑한다는 말도."
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "あと、愛しているってこともな。"
L24_1.m_Talk_JPN = L25_1
L25_1 = "And... tell him that I love him."
L24_1.m_Talk_ENG = L25_1
L25_1 = "還有告訴他我愛他。"
L24_1.m_Talk_TWN = L25_1
L25_1 = "แล้วก็... บอกเขาด้วยว่าผมรักเขา"
L24_1.m_Talk_THA = L25_1
L25_1 = "Và ... nói với anh ấy rằng tôi yêu quý anh ấy."
L24_1.m_Talk_VTN = L25_1
L25_1 = "还有请告诉他我爱他。"
L24_1.m_Talk_SCN = L25_1
L25_1 = "Und … sag ihm, dass ich ihn lieb habe."
L24_1.m_Talk_DEU = L25_1
L25_1 = "Et... dites-lui que je l'aime."
L24_1.m_Talk_FRA = L25_1
L25_1 = {}
