L29_1 = "아마 이 영상을 보게 되면 넌 내게 미친 듯이 화를 내겠지만......"
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "この動画を見たら、君は怒り狂うだろうが……"
L28_1.m_Talk_JPN = L29_1
L29_1 = "I know you'll be mad as hell if you ever get to see this,"
L28_1.m_Talk_ENG = L29_1
L29_1 = "妳看到這個影片，大概會對我發飆吧。"
L28_1.m_Talk_TWN = L29_1
L29_1 = "ผมรู้ว่าคุณคงโกรธเป็นบ้าเลย ถ้าได้ดูวิดีโอนี้"
L28_1.m_Talk_THA = L29_1
L29_1 = "Tôi biết bạn sẽ phát điên nếu bạn thấy điều này,"
L28_1.m_Talk_VTN = L29_1
L29_1 = "大概你看到这个视频，会发狂一样地冲我发火吧……"
L28_1.m_Talk_SCN = L29_1
L29_1 = "ich weiß, dass du stinksauer sein wirst, falls du das je zu sehen bekommst."
L28_1.m_Talk_DEU = L29_1
L29_1 = "je sais que tu seras furieuse si jamais tu vois ça un jour,"
L28_1.m_Talk_FRA = L29_1
L29_1 = {}
L30_1 = "EP5_ACT1_PROLOGUE@129#Talk"
L29_1.m_CutScenKey_Talk = L30_1
L30_1 = 129
L29_1.m_CutScenProcessKey = L30_1
L29_1.m_CutScenID = 159
L29_1.m_CutScenStrID = "EP5_ACT1_PROLOGUE"
L29_1.m_bWaitClick = true
L29_1.m_fWaitTime = 0
L29_1.m_CharStrID = "IAN_EXTRA_NULL_NULL"
L30_1 = "이렇게 위험한 일에 동료를 말려들게 할 순 없어서 말이지."
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "こんな危険な仕事に仲間を巻き込むわけにはいかないんだ。"
L29_1.m_Talk_JPN = L30_1
L30_1 = "but I just couldn't ask others for help in something this dangerous."
L29_1.m_Talk_ENG = L30_1
L30_1 = "畢竟我不希望我工作上的夥伴被捲入這麼危險的事情。"
L29_1.m_Talk_TWN = L30_1
L30_1 = "แต่ผมแค่ขอให้คนอื่นช่วยทำเรื่องอันตรายขนาดนี้ไม่ได้"
L29_1.m_Talk_THA = L30_1
L30_1 = "nhưng tôi không thể nhờ người khác giúp đỡ trong một việc nguy hiểm như thế này."
L29_1.m_Talk_VTN = L30_1
L30_1 = "虽然我不希望我的同事卷入这么危险的事儿。"
L29_1.m_Talk_SCN = L30_1
L30_1 = "Aber ich konnte bei etwas so Gefährlichem niemand sonst um Hilfe bitten."
L29_1.m_Talk_DEU = L30_1
L30_1 = "mais je ne pouvais pas demander de l'aide pour quelque chose d'aussi dangereux."
L29_1.m_Talk_FRA = L30_1
L30_1 = {}
L31_1 = "EP5_ACT1_PROLOGUE@130#Talk"
L30_1.m_CutScenKey_Talk = L31_1
L31_1 = 130
L30_1.m_CutScenProcessKey = L31_1
L30_1.m_CutScenID = 159
L30_1.m_CutScenStrID = "EP5_ACT1_PROLOGUE"
L30_1.m_bWaitClick = true
L30_1.m_fWaitTime = 0
L30_1.m_CharStrID = "IAN_EXTRA_NULL_NULL"
L31_1 = "만약 내가 실패한다면...... 뒤를 부탁한다."
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "もし私が失敗したら……後を頼む。"
L30_1.m_Talk_JPN = L31_1
L31_1 = "If I fail, please take care of things in my stead."
L30_1.m_Talk_ENG = L31_1
L31_1 = "但如果我失敗了的話……之後就拜託妳了。"
L30_1.m_Talk_TWN = L31_1
L31_1 = "ถ้าผมพลาด ช่วยดูแลอะไรๆ แทนผมด้วยนะ"
L30_1.m_Talk_THA = L31_1
L31_1 = "Nếu tôi thất bại, xin hãy chăm lo mọi thứ thay tôi."
L30_1.m_Talk_VTN = L31_1
L31_1 = "如果我失败了的话……以后就拜托了。"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Wenn ich scheitere, erledige bitte alles an meiner statt."
L30_1.m_Talk_DEU = L31_1
L31_1 = "Si j'échoue, s'il te plaît prends le relais à ma place."
L30_1.m_Talk_FRA = L31_1
L31_1 = {}
L32_1 = "EP5_ACT1_PROLOGUE@131#Talk"
L31_1.m_CutScenKey_Talk = L32_1
L32_1 = 131
L31_1.m_CutScenProcessKey = L32_1
L31_1.m_CutScenID = 159
L31_1.m_CutScenStrID = "EP5_ACT1_PROLOGUE"
L31_1.m_bWaitClick = true
L31_1.m_fWaitTime = 0
L31_1.m_CharStrID = "IAN_EXTRA_NULL_NULL"
L32_1 = "가급적이면 어딘가 멀리 도망쳐서 안전하게 살길 바라지만......"
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "できればどこか遠くへ逃げて、安全に暮らしてほしいが……"
L31_1.m_Talk_JPN = L32_1
L32_1 = "I would really like to tell you to run and live on in safety..."
L31_1.m_Talk_ENG = L32_1
L32_1 = "可以的話，希望妳能逃到很遠的地方，過上安全的生活。"
L31_1.m_Talk_TWN = L32_1
L32_1 = "ผมอยากบอกให้คุณหนีไปซะ แล้วไปใช้ชีวิตที่ปลอดภัย"
L31_1.m_Talk_THA = L32_1
L32_1 = "Tôi thực sự muốn nói với bạn rằng hãy chạy đi và sống an toàn..."
L31_1.m_Talk_VTN = L32_1
L32_1 = "若可能的话，希望你能逃到很远的地方，过上平安快乐的生活。"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Ich würde dir gerne sagen, dass du fliehen und in Sicherheit leben sollst …"
L31_1.m_Talk_DEU = L32_1
L32_1 = "J'aimerais pouvoir te dire de t'enfuir et de te mettre en sécurité..."
L31_1.m_Talk_FRA = L32_1
L32_1 = {}
L33_1 = "EP5_ACT1_PROLOGUE@132#Talk"
L32_1.m_CutScenKey_Talk = L33_1
L33_1 = 132
L32_1.m_CutScenProcessKey = L33_1
L32_1.m_CutScenID = 159
L32_1.m_CutScenStrID = "EP5_ACT1_PROLOGUE"
L32_1.m_bWaitClick = true
L32_1.m_fWaitTime = 0
L32_1.m_CharStrID = "IAN_EXTRA_NULL_NULL"
L33_1 = "내가 아는 너라면 절대 그렇게 하지 않을 테니까."
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "私の知る君なら、決してそうはしないだろうな。"
L32_1.m_Talk_JPN = L33_1
L33_1 = "But I know too well that it's not something you're going to do."
L32_1.m_Talk_ENG = L33_1
L33_1 = "但我認識的妳絕對不會這麼做。"
L32_1.m_Talk_TWN = L33_1
L33_1 = "แต่ผมก็รู้ดีว่าคุณจะไม่ทำแบบนั้น"
L32_1.m_Talk_THA = L33_1
L33_1 = "Nhưng tôi biết quá rõ rằng đó không phải là điều bạn sẽ làm."
L32_1.m_Talk_VTN = L33_1
L33_1 = "虽然我知道我认识的简，是不会这么做。"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Aber ich weiß nur zu gut, dass du das nicht tun wirst."
L32_1.m_Talk_DEU = L33_1
L33_1 = "Mais je sais parfaitement que ce n'est pas ce que tu vas faire."
L32_1.m_Talk_FRA = L33_1
L33_1 = {}
L34_1 = "EP5_ACT1_PROLOGUE@133#Talk"
L33_1.m_CutScenKey_Talk = L34_1
L34_1 = 133
L33_1.m_CutScenProcessKey = L34_1
L33_1.m_CutScenID = 159
L33_1.m_CutScenStrID = "EP5_ACT1_PROLOGUE"
L33_1.m_bWaitClick = true
L33_1.m_fWaitTime = 0
L33_1.m_CharStrID = "IAN_EXTRA_NULL_NULL"
L34_1 = "당신은 포기나 굴복 따윈 모르는 정말 멋진 여자니까."
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "君は諦めや屈服なんて言葉を知らない、本物のカッコいい女だからな。"
L33_1.m_Talk_JPN = L34_1
L34_1 = "A strong, fine woman like you does not give in."
L33_1.m_Talk_ENG = L34_1
L34_1 = "因為妳是一個不知道什麼是放棄或屈服的好女孩。"
L33_1.m_Talk_TWN = L34_1
L34_1 = "ผู้หญิงดีๆ ที่เข้มแข็งแบบคุณไม่มีวันยอมแพ้"
L33_1.m_Talk_THA = L34_1
L34_1 = "Một người phụ nữ tốt, mạnh mẽ như bạn không nhượng bộ."
L33_1.m_Talk_VTN = L34_1
L34_1 = "因为你是一个不知道放弃或屈服的一个特别帅气的女孩。"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Eine starke, gute Frau wie du gibt nicht auf."
L33_1.m_Talk_DEU = L34_1
L34_1 = "Une belle femme forte comme toi n'abandonne jamais."
L33_1.m_Talk_FRA = L34_1
L34_1 = {}
L35_1 = "EP5_ACT1_PROLOGUE@134#Talk"
L34_1.m_CutScenKey_Talk = L35_1
L35_1 = 134
L34_1.m_CutScenProcessKey = L35_1
L34_1.m_CutScenID = 159
L34_1.m_CutScenStrID = "EP5_ACT1_PROLOGUE"
L34_1.m_bWaitClick = true
L34_1.m_fWaitTime = 0
L34_1.m_CharStrID = "IAN_EXTRA_NULL_NULL"
L35_1 = "어차피 싸울 거라면...... 행운이 함께 하기를 빌게."
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "どのみち戦うつもりなら……幸運を祈るよ。"
L34_1.m_Talk_JPN = L35_1
L35_1 = "So for your future struggles, I wish you all the luck in the world."
L34_1.m_Talk_ENG = L35_1
L35_1 = "反正都要戰鬥的話……那不如就願好運與妳同在吧。"
L34_1.m_Talk_TWN = L35_1
L35_1 = "ดังนั้นผมก็ขอให้คุณโชคดี สำหรับสิ่งที่คุณจะต้องสู้ต่อไปในอนาคตนะ"
L34_1.m_Talk_THA = L35_1
L35_1 = "Vì vậy, tôi chúc bạn luôn may mắn trước những khó khăn phải đối mặt  trong tương lai."
L34_1.m_Talk_VTN = L35_1
L35_1 = "希望幸运与你相伴。"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Für deine zukünftigen Konflikte wünsche ich dir also alles Glück der Welt."
L34_1.m_Talk_DEU = L35_1
L35_1 = "Alors, pour toutes tes prochaines batailles, je te souhaite toute la chance du monde."
L34_1.m_Talk_FRA = L35_1
L35_1 = {}
L36_1 = "EP5_ACT1_PROLOGUE@135#Talk"
L35_1.m_CutScenKey_Talk = L36_1
L36_1 = 135
L35_1.m_CutScenProcessKey = L36_1
L35_1.m_CutScenID = 159
L35_1.m_CutScenStrID = "EP5_ACT1_PROLOGUE"
L35_1.m_bWaitClick = true
L35_1.m_fWaitTime = 0
L35_1.m_CharStrID = "IAN_EXTRA_NULL_NULL"
L36_1 = "당신의 영원한 친구, 이안으로부터."
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "君の永遠の友、イアンより。"
L35_1.m_Talk_JPN = L36_1
L36_1 = "These are the last words from your friend, Ian."
L35_1.m_Talk_ENG = L36_1
L36_1 = "妳永遠的朋友，伊恩。"
L35_1.m_Talk_TWN = L36_1
L36_1 = "นี่คือคำพูดสุดท้ายจากเพื่อนของคุณ เอียน"
L35_1.m_Talk_THA = L36_1
L36_1 = "Đây là những lời cuối cùng từ người bạn của bạn, Ian."
L35_1.m_Talk_VTN = L36_1
L36_1 = "你永远的朋友-伊恩。"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Dies sind die letzten Worte deines Freundes Ian."
L35_1.m_Talk_DEU = L36_1
L36_1 = "Ce sont les derniers mots de ton ami, Ian."
L35_1.m_Talk_FRA = L36_1
L36_1 = {}
