L43_1 = "잘 봤습니다. 메이슨 씨."
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "見せていただきありがとうございます。メイソンさん。"
L42_1.m_Talk_JPN = L43_1
L43_1 = "Thank you, Mr. Mason."
L42_1.m_Talk_ENG = L43_1
L43_1 = "我看完了，梅森先生。"
L42_1.m_Talk_TWN = L43_1
L43_1 = "ขอบคุณ คุณเมสัน"
L42_1.m_Talk_THA = L43_1
L43_1 = "Cảm ơn, ngài Mason."
L42_1.m_Talk_VTN = L43_1
L43_1 = "我看完了，梅森先生。"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Vielen Dank, John."
L42_1.m_Talk_DEU = L43_1
L43_1 = "Merci, Monsieur Mason."
L42_1.m_Talk_FRA = L43_1
L43_1 = {}
L44_1 = "EP5_ACT1_PROLOGUE@143#Talk"
L43_1.m_CutScenKey_Talk = L44_1
L44_1 = 143
L43_1.m_CutScenProcessKey = L44_1
L43_1.m_CutScenID = 159
L43_1.m_CutScenStrID = "EP5_ACT1_PROLOGUE"
L43_1.m_bWaitClick = true
L43_1.m_fWaitTime = 0
L43_1.m_CharStrID = "JOOSHIYOON_FENRIR_NULL_NULL"
L43_1.m_Pos = "C"
L44_1 = "일련의 의문들이 모두 해결되네요."
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "一連の謎が一気に解けましたね。"
L43_1.m_Talk_JPN = L44_1
L44_1 = "That answers a lot of questions."
L43_1.m_Talk_ENG = L44_1
L44_1 = "我一連串的疑問全部解決了呢。"
L43_1.m_Talk_TWN = L44_1
L44_1 = "ตอบคำถามได้หลายอย่างเลย"
L43_1.m_Talk_THA = L44_1
L44_1 = "Điều đó đã trả lời rất nhiều câu hỏi."
L43_1.m_Talk_VTN = L44_1
L44_1 = "解决了我一连串的疑问呢。"
L43_1.m_Talk_SCN = L44_1
L44_1 = "Das beantwortet eine Menge Fragen."
L43_1.m_Talk_DEU = L44_1
L44_1 = "Ça répond à beaucoup de questions."
L43_1.m_Talk_FRA = L44_1
