L50_1 = "그 리플레이서 간부 후보생......"
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "あのリプレイサー幹部候補生というのは……"
L49_1.m_Talk_JPN = L50_1
L50_1 = "That officer candidate he was talking about..."
L49_1.m_Talk_ENG = L50_1
L50_1 = "那個克隆集團幹部候補生……"
L49_1.m_Talk_TWN = L50_1
L50_1 = "อาสาสมัครเจ้าหน้าที่ที่เขาพูดถึง..."
L49_1.m_Talk_THA = L50_1
L50_1 = "Ứng viên sĩ quan mà anh ta đang nói đến..."
L49_1.m_Talk_VTN = L50_1
L50_1 = "那个提到的克隆集团的头目候补生……"
L49_1.m_Talk_SCN = L50_1
L50_1 = "Der Offiziersanwärter, den er erwähnte …"
L49_1.m_Talk_DEU = L50_1
L50_1 = "La candidate officier dont il parlait..."
L49_1.m_Talk_FRA = L50_1
L50_1 = {}
L51_1 = "EP5_ACT1_PROLOGUE@150#Talk"
L50_1.m_CutScenKey_Talk = L51_1
L51_1 = 150
L50_1.m_CutScenProcessKey = L51_1
L50_1.m_CutScenID = 159
