L50_1.m_Pos = "L"
L51_1 = "이름은 나오지 않았지만, 아마 나이트였겠죠?"
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "名前こそ出ていないですが、おそらくナイトですよね？"
L50_1.m_Talk_JPN = L51_1
L51_1 = "He didn't mention any names, but I'd assume it was Knight."
L50_1.m_Talk_ENG = L51_1
L51_1 = "雖然名字沒有提及，但大概是騎士吧？"
L50_1.m_Talk_TWN = L51_1
L51_1 = "เขาไม่ได้เอ่ยชื่อ แต่ผมเดาว่านั่นคือไนท์"
L50_1.m_Talk_THA = L51_1
L51_1 = "Anh ta không đề cập đến bất kỳ cái tên nào, nhưng tôi cho rằng đó là Quân Mã."
L50_1.m_Talk_VTN = L51_1
L51_1 = "虽然名字没有提及，但大概是骑士长吧？"
L50_1.m_Talk_SCN = L51_1
L51_1 = "Er nannte keine Namen, aber ich nehme an, es war Knight."
L50_1.m_Talk_DEU = L51_1
L51_1 = "Il a pas donné de nom, mais j'imagine que c'était le cavalier."
L50_1.m_Talk_FRA = L51_1
