L3_1 = "EP5_ACT1_PROLOGUE@152#Talk"
L2_1.m_CutScenKey_Talk = L3_1
L3_1 = 152
L2_1.m_CutScenProcessKey = L3_1
L2_1.m_CutScenID = 159
L2_1.m_CutScenStrID = "EP5_ACT1_PROLOGUE"
L2_1.m_bWaitClick = true
L2_1.m_fWaitTime = 0
L2_1.m_CharStrID = "JOOSHIYOON_FENRIR_NULL_NULL"
L2_1.m_Pos = "L"
L3_1 = "KS-1에 잠입했던 것도, 나이트와 조우해서 베리칩의 정보를 빼내기 위해서였겠군요."
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "KS-1に潜入したのも、ナイトと会ってベリーチップの情報を抜き取るためだったんでしょうね。"
L2_1.m_Talk_JPN = L3_1
L3_1 = "So sneaking into KS-1 was to approach Knight and retrieve the data from her VeriChip."
L2_1.m_Talk_ENG = L3_1
L3_1 = "你潛入KS-1，也是為了遇到騎士，取得超級晶片的情報吧。"
L2_1.m_Talk_TWN = L3_1
L3_1 = "เขาแอบเข้าไปใน KS-1 เพื่อเข้าหาไนท์ แล้วก็กู้ข้อมูลจาก VeriChip ของเธอ"
L2_1.m_Talk_THA = L3_1
L3_1 = "Vì vậy, lẻn vào KS-1 là để tiếp cận Quân Mã và lấy dữ liệu từ VeriChip của cô ấy."
L2_1.m_Talk_VTN = L3_1
L3_1 = "潜入KS-1，也是为了与骑士长相遇，窃取超级芯片的信息吧。"
L2_1.m_Talk_SCN = L3_1
L3_1 = "Die Aktion in KS-1 diente also dazu, sich Knight zu nähern und die Daten von ihrem VeriChip abzurufen."
L2_1.m_Talk_DEU = L3_1
L3_1 = "Donc l'infiltration de KS-1 c'était pour approcher le cavalier et récupérer sa VériPuce."
L2_1.m_Talk_FRA = L3_1
L3_1 = {}
