L4_1 = "맞아."
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "そのとおりだ。"
L3_1.m_Talk_JPN = L4_1
L4_1 = "Exactly."
L3_1.m_Talk_ENG = L4_1
L4_1 = "對。"
L3_1.m_Talk_TWN = L4_1
L4_1 = "ถูกต้อง"
L3_1.m_Talk_THA = L4_1
L4_1 = "Chính xác."
L3_1.m_Talk_VTN = L4_1
L4_1 = "对。"
L3_1.m_Talk_SCN = L4_1
L4_1 = "So ist es."
L3_1.m_Talk_DEU = L4_1
L4_1 = "Voilà."
L3_1.m_Talk_FRA = L4_1
L4_1 = {}
L5_1 = "EP5_ACT1_PROLOGUE@154#Talk"
L4_1.m_CutScenKey_Talk = L5_1
L5_1 = 154
L4_1.m_CutScenProcessKey = L5_1
L4_1.m_CutScenID = 159
L4_1.m_CutScenStrID = "EP5_ACT1_PROLOGUE"
L4_1.m_bWaitClick = true
L4_1.m_fWaitTime = 0
L4_1.m_CharStrID = "JOOSHIYOON_FENRIR_NULL_NULL"
L4_1.m_Pos = "L"
L5_1 = "하지만 굳이 리플레이서 간부의 몸에 데이터를 숨긴 건 이상하네요. 그럴 필요가 있었을까요?"
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "けど、あえてリプレイサー幹部の体にデータを隠したのは不自然ですね。\nそんな必要あったのでしょうか。"
L4_1.m_Talk_JPN = L5_1
L5_1 = "But why hide the data inside the body of a Replacer officer? I don't see how it was necessary."
L4_1.m_Talk_ENG = L5_1
L5_1 = "但刻意把數據藏在克隆集團幹部的身上，真是件怪事呢。有必要這樣做嗎？"
L4_1.m_Talk_TWN = L5_1
L5_1 = "แต่ทำไมถึงต้องซ่อนข้อมูลไว้ในร่างของเจ้าหน้าที่รีเพลสเซอร์ล่ะ? ไม่เข้าใจว่ามันจำเป็นตรงไหน"
L4_1.m_Talk_THA = L5_1
L5_1 = "Nhưng tại sao lại giấu dữ liệu bên trong cơ thể của một sĩ quan Nhân Bản? Tôi không thấy việc đó cần thiết."
L4_1.m_Talk_VTN = L5_1
L5_1 = "但是把数据藏在克隆集团头目的身上，真是怪事啊。有这样做的必要吗？"
L4_1.m_Talk_SCN = L5_1
L5_1 = "Aber warum wurden die Daten im Körper eines Replacer-Offiziers versteckt? Ich verstehe nicht, wozu das notwendig war."
L4_1.m_Talk_DEU = L5_1
L5_1 = "Mais pourquoi cacher les données dans le corps d'un officier des substituts ? Je ne vois pas en quoi c'était nécessaire."
L4_1.m_Talk_FRA = L5_1
L5_1 = {}
L6_1 = "EP5_ACT1_PROLOGUE@155#Talk"
L5_1.m_CutScenKey_Talk = L6_1
L6_1 = 155
L5_1.m_CutScenProcessKey = L6_1
L5_1.m_CutScenID = 159
L5_1.m_CutScenStrID = "EP5_ACT1_PROLOGUE"
L5_1.m_bWaitClick = true
L5_1.m_fWaitTime = 0
L6_1 = "UNIT_LAUGH"
L5_1.m_Face = L6_1
L5_1.m_CharStrID = "JOHN_MASON_NULL_NULL"
L5_1.m_Pos = "R"
L6_1 = "내 형이지만 성격이 괴팍해서 말이야."
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "俺の兄貴ながら、偏屈な性格でな。"
L5_1.m_Talk_JPN = L6_1
L6_1 = "My brother had eccentric inclinations."
L5_1.m_Talk_ENG = L6_1
L6_1 = "他雖然是我的哥哥，但性格卻有點古怪。"
L5_1.m_Talk_TWN = L6_1
L6_1 = "พี่ชายผมชอบทำอะไรแปลกๆ น่ะ"
L5_1.m_Talk_THA = L6_1
L6_1 = "Anh trai tôi có khuynh hướng lập dị."
L5_1.m_Talk_VTN = L6_1
L6_1 = "他虽然是我的哥哥，但性格的确古怪。"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Mein Bruder hatte exzentrische Neigungen."
L5_1.m_Talk_DEU = L6_1
L6_1 = "Mon frère avait des penchants excentriques."
L5_1.m_Talk_FRA = L6_1
L6_1 = {}
L7_1 = "EP5_ACT1_PROLOGUE@156#Talk"
L6_1.m_CutScenKey_Talk = L7_1
L7_1 = 156
L6_1.m_CutScenProcessKey = L7_1
L6_1.m_CutScenID = 159
L6_1.m_CutScenStrID = "EP5_ACT1_PROLOGUE"
L6_1.m_bWaitClick = true
L6_1.m_fWaitTime = 0
L6_1.m_CharStrID = "JOHN_MASON_NULL_NULL"
L6_1.m_Pos = "R"
L7_1 = "아마 그 녀석을 처치할 실력이 되지 않으면 애초에 시도도 하지 말라는 뜻이겠지."
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "たぶん、奴を始末できる力がなけりゃ、そもそも手を出すなということだろう。"
L6_1.m_Talk_JPN = L7_1
L7_1 = "Perhaps he wanted to say we shouldn't even try to stop the entire organization if we weren't strong enough to defeat her."
L6_1.m_Talk_ENG = L7_1
L7_1 = "他可能是想告訴我，如果連除掉這個傢伙的實力都沒有，那從一開始就不要去嘗試吧。"
L6_1.m_Talk_TWN = L7_1
L7_1 = "เขาอาจจะอยากบอกว่า เราไม่ควรแม้แต่จะพยายามหยุดทั้งองค์กร หากเรายังไม่แข็งแกร่งพอที่จะเอาชนะเธอ"
L6_1.m_Talk_THA = L7_1
L7_1 = "Có lẽ anh ấy muốn nói rằng chúng tôi thậm chí không nên cố gắng ngăn chặn toàn bộ tổ chức nếu chúng tôi không đủ mạnh để đánh bại cô ấy."
L6_1.m_Talk_VTN = L7_1
L7_1 = "他可能是想告诉我，如果连除掉这个家伙的实力都没有的话，就不要去挑战吧。"
L6_1.m_Talk_SCN = L7_1
L7_1 = "Vielleicht wollte er, dass wir gar nicht erst versuchen, die gesamte Organisation zu stoppen, wenn wir nicht mal stark genug sind, sie zu besiegen."
L6_1.m_Talk_DEU = L7_1
L7_1 = "Il voulait peut-être nous faire comprendre que si nous n'étions pas capables de la vaincre il était inutile de songer à stopper l'organisation."
L6_1.m_Talk_FRA = L7_1
L7_1 = {}
L8_1 = "EP5_ACT1_PROLOGUE@157#Talk"
L7_1.m_CutScenKey_Talk = L8_1
L8_1 = 157
L7_1.m_CutScenProcessKey = L8_1
L7_1.m_CutScenID = 159
L7_1.m_CutScenStrID = "EP5_ACT1_PROLOGUE"
L7_1.m_bWaitClick = true
L7_1.m_fWaitTime = 0
L7_1.m_CharStrID = "JOOSHIYOON_FENRIR_NULL_NULL"
L7_1.m_Pos = "L"
L8_1 = "그렇군요. 그럼 제인 도우라는 분은 누구죠?"
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "なるほど、では、ジェーン・ドウという方は？"
L7_1.m_Talk_JPN = L8_1
L8_1 = "I see. Who is this Jane Doe then?"
L7_1.m_Talk_ENG = L8_1
L8_1 = "原來如此，但那個叫作珍妮．多伊的是誰啊？"
L7_1.m_Talk_TWN = L8_1
L8_1 = "เข้าใจละ แล้วใครคือเจน โด?"
L7_1.m_Talk_THA = L8_1
L8_1 = "Tôi hiểu rồi. Vậy Jane Doe là ai?"
L7_1.m_Talk_VTN = L8_1
L8_1 = "这样啊，那谁是简呢？"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Verstehe. Und wer ist diese Jane Doe?"
L7_1.m_Talk_DEU = L8_1
L8_1 = "Je vois. Mais qui est cette Jane Doe alors ?"
L7_1.m_Talk_FRA = L8_1
L8_1 = {}
L9_1 = "EP5_ACT1_PROLOGUE@158#Talk"
L8_1.m_CutScenKey_Talk = L9_1
L9_1 = 158
L8_1.m_CutScenProcessKey = L9_1
L8_1.m_CutScenID = 159
L8_1.m_CutScenStrID = "EP5_ACT1_PROLOGUE"
L8_1.m_bWaitClick = true
L8_1.m_fWaitTime = 0
L8_1.m_CharStrID = "JOOSHIYOON_FENRIR_NULL_NULL"
L8_1.m_Pos = "L"
L9_1 = "신원 미상이라니, 이름부터 심상치 않은데요."
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "身元不明者を象徴する名前からして、並ならぬ印象ですね。"
L8_1.m_Talk_JPN = L9_1
L9_1 = "I must say, it's a very odd name."
L8_1.m_Talk_ENG = L9_1
L9_1 = "不但身份不詳，光是名字就不太尋常。"
L8_1.m_Talk_TWN = L9_1
L9_1 = "ขอบอกว่าเป็นชื่อที่แปลกมาก"
L8_1.m_Talk_THA = L9_1
L9_1 = "Tôi phải nói rằng, đó là một cái tên rất kỳ quặc."
L8_1.m_Talk_VTN = L9_1
L9_1 = "这人身份不详，连名字开始就非同寻常。"
L8_1.m_Talk_SCN = L9_1
L9_1 = "Das ist ein merkwürdiger Name, finde ich."
L8_1.m_Talk_DEU = L9_1
L9_1 = "Je dois dire que c'est un nom plutôt étrange."
L8_1.m_Talk_FRA = L9_1
