L10_1 = "UNIT_IDLE"
L9_1.m_Face = L10_1
L9_1.m_CharStrID = "JOHN_MASON_NULL_NULL"
L9_1.m_Pos = "R"
L10_1 = "......원래는 형과 함께 리플레이서 측에 연구원 겸 연락책으로 고용됐던 사람이다."
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "……元々は兄とともに、リプレイサー側の研究員兼連絡係として雇われていた人物だ。"
L9_1.m_Talk_JPN = L10_1
L10_1 = "She was the one who was hired as a researcher and liaison by the Replacer Syndicate with my brother."
L9_1.m_Talk_ENG = L10_1
L10_1 = "……她原本是跟哥哥一起被克隆集團錄用的研究員，並兼任聯絡窗口。"
L9_1.m_Talk_TWN = L10_1
L10_1 = "เธอเป็นหนึ่งในคนที่รีเพลสเซอร์ซินดิเคตจ้างมาในฐานะนักวิจัย\nและเจ้าหน้าที่ติดต่อประสานงาน พร้อมกับพี่ชายของฉัน"
L9_1.m_Talk_THA = L10_1
L10_1 = "Cô ấy được thuê làm nghiên cứu viên và liên lạc với Nghiệp Đoàn Nhân Bản thông qua anh tôi."
L9_1.m_Talk_VTN = L10_1
L10_1 = "……她是跟哥哥一起被克隆集团聘为研究员，兼任联络人的人。"
L9_1.m_Talk_SCN = L10_1
L10_1 = "Sie wurde vom Replacer-Syndikat als Forscherin und Verbindungsperson mit meinem Bruder eingestellt."
L9_1.m_Talk_DEU = L10_1
L10_1 = "Elle a été embauchée par le Syndicat des substituts comme agent de liaison pour faire de la recherche avec mon frère."
L9_1.m_Talk_FRA = L10_1
L10_1 = {}
