L11_1.m_fWaitTime = 0
L11_1.m_CharStrID = "JOOSHIYOON_FENRIR_NULL_NULL"
L11_1.m_Pos = "L"
L12_1 = "그렇다는 건...... 진짜 임무는 연락책이 아니라......"
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "ということは……本当の役目は連絡係ではなく……"
L11_1.m_Talk_JPN = L12_1
L12_1 = "If that’s the case, her real duty was..."
L11_1.m_Talk_ENG = L12_1
L12_1 = "這麼說的話……她真正的任務就不是當聯絡窗口……"
L11_1.m_Talk_TWN = L12_1
L12_1 = "ถ้าอย่างนั้น หน้าที่จริงๆ ของเธอก็คือ..."
L11_1.m_Talk_THA = L12_1
L12_1 = "Nếu đúng như vậy, nhiệm vụ thực sự của cô ấy là ..."
L11_1.m_Talk_VTN = L12_1
L12_1 = "这样一来……真正的任务其实不是联络人……"
L11_1.m_Talk_SCN = L12_1
L12_1 = "Wenn das der Fall ist, war ihre eigentliche Aufgabe …"
L11_1.m_Talk_DEU = L12_1
L12_1 = "Mais dans ce cas, son vrai rôle était..."
L11_1.m_Talk_FRA = L12_1
