L13_1 = "EP5_ACT1_PROLOGUE@162#Talk"
L12_1.m_CutScenKey_Talk = L13_1
L13_1 = 162
L12_1.m_CutScenProcessKey = L13_1
L12_1.m_CutScenID = 159
L12_1.m_CutScenStrID = "EP5_ACT1_PROLOGUE"
L12_1.m_bWaitClick = true
L12_1.m_fWaitTime = 0
L12_1.m_CharStrID = "JOHN_MASON_NULL_NULL"
L12_1.m_Pos = "R"
L13_1 = "그래. 아마 감시역이었겠지."
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "まあ、監視係だったろうよ。"
L12_1.m_Talk_JPN = L13_1
L13_1 = "Yes. She was probably hired to keep an eye on him."
L12_1.m_Talk_ENG = L13_1
L13_1 = "沒錯，應該是監視者吧。"
L12_1.m_Talk_TWN = L13_1
L13_1 = "ใช่ เธอน่าจะถูกจ้างมาให้จับตาดูเขา"
L12_1.m_Talk_THA = L13_1
L13_1 = "Đúng. Cô ấy có lẽ được thuê để theo dõi anh ta."
L12_1.m_Talk_VTN = L13_1
L13_1 = "是担任监视的一职。"
L12_1.m_Talk_SCN = L13_1
L13_1 = "Ja. Sie wurde wahrscheinlich eingestellt, um ihn im Auge zu behalten."
L12_1.m_Talk_DEU = L13_1
L13_1 = "Oui. Elle a probablement été embauchée pour le surveiller."
L12_1.m_Talk_FRA = L13_1
