L14_1 = "EP5_ACT1_PROLOGUE@163#Talk"
L13_1.m_CutScenKey_Talk = L14_1
L14_1 = 163
L13_1.m_CutScenProcessKey = L14_1
L13_1.m_CutScenID = 159
L13_1.m_CutScenStrID = "EP5_ACT1_PROLOGUE"
L13_1.m_bWaitClick = true
L13_1.m_fWaitTime = 0
L13_1.m_CharStrID = "JOHN_MASON_NULL_NULL"
L13_1.m_Pos = "R"
L14_1 = "하지만 무슨 심경의 변화가 있었는지 형이 죽은 후로 그녀도 리플레이서에 등을 돌린 것 같더군."
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "だが、どういう風の吹き回しか兄貴の死後、彼女もリプレイサーに背を向けたようなんだ。"
L13_1.m_Talk_JPN = L14_1
L14_1 = "But it seems she left the Syndicate after Ian's death, for whatever reason."
L13_1.m_Talk_ENG = L14_1
L14_1 = "但不知道她心理發生了什麼變化，哥哥死了之後，她好像也背叛了克隆集團。"
L13_1.m_Talk_TWN = L14_1
L14_1 = "แต่ดูเหมือนว่าเธอจะออกจากซินดิเคตหลังเอียนเสียชีวิต ไม่รู้ว่าด้วยเหตุผลอะไร"
L13_1.m_Talk_THA = L14_1
L14_1 = "Nhưng có vẻ như cô ấy đã rời khỏi Syndicate sau cái chết của Ian, vì lý do nào đó."
L13_1.m_Talk_VTN = L14_1
L14_1 = "但不知道是不是因为哥哥的死因，她最后好像也背叛了克隆集团。"
L13_1.m_Talk_SCN = L14_1
L14_1 = "Aber es scheint, dass sie das Syndikat nach Ians Tod verließ … Aus welchem Grund auch immer."
L13_1.m_Talk_DEU = L14_1
L14_1 = "Mais, pour je ne sais quelle raison, elle a quitté le Syndicat après la mort de mon frère."
L13_1.m_Talk_FRA = L14_1
L14_1 = {}
L15_1 = "EP5_ACT1_PROLOGUE@164#Talk"
L14_1.m_CutScenKey_Talk = L15_1
L15_1 = 164
L14_1.m_CutScenProcessKey = L15_1
L14_1.m_CutScenID = 159
L14_1.m_CutScenStrID = "EP5_ACT1_PROLOGUE"
L14_1.m_bWaitClick = true
L14_1.m_fWaitTime = 0
L14_1.m_CharStrID = "JOHN_MASON_NULL_NULL"
L14_1.m_Pos = "R"
L15_1 = "그 후에는 그녀 단독으로 테라사이드 시스템 관련 정보를 수집하고 있었고."
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "それ以降、彼女は一人でテラサイドシステムに関する情報を集めていた。"
L14_1.m_Talk_JPN = L15_1
L15_1 = "And she's been collecting information on System Terraside on her own ever since."
L14_1.m_Talk_ENG = L15_1
L15_1 = "之後她就一個人一直在收集和特拉賽德系統有關的情報。"
L14_1.m_Talk_TWN = L15_1
L15_1 = "และเธอก็รวบรวมข้อมูลเกี่ยวกับระบบเทอร์ราไซด์ด้วยตัวเองนับแต่นั้นมา"
L14_1.m_Talk_THA = L15_1
L15_1 = "Và cô ấy đã tự mình thu thập thông tin trên Terraside Hệ Thống kể từ đó."
L14_1.m_Talk_VTN = L15_1
L15_1 = "此后她一直在单独收集和特拉赛德系统有关的信息。"
L14_1.m_Talk_SCN = L15_1
L15_1 = "Seitdem sammelt sie auf eigene Faust Informationen über das Terraside-System."
L14_1.m_Talk_DEU = L15_1
L15_1 = "Et depuis, elle rassemble des informations sur le système Terremonde de son côté."
L14_1.m_Talk_FRA = L15_1
L15_1 = {}
L16_1 = "EP5_ACT1_PROLOGUE@165#Talk"
L15_1.m_CutScenKey_Talk = L16_1
L16_1 = 165
L15_1.m_CutScenProcessKey = L16_1
L15_1.m_CutScenID = 159
L15_1.m_CutScenStrID = "EP5_ACT1_PROLOGUE"
L15_1.m_bWaitClick = true
L15_1.m_fWaitTime = 0
L15_1.m_CharStrID = "JOHN_MASON_NULL_NULL"
L15_1.m_Pos = "R"
L16_1 = "내가 형의 유언을 입수한 것도 사실 그 여자를 통해서였어."
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "実は兄貴の遺言も、その女から手に入れたんだ。"
L15_1.m_Talk_JPN = L16_1
L16_1 = "As a matter of fact, it was through her that I was able to get Ian's video."
L15_1.m_Talk_ENG = L16_1
L16_1 = "事實上，我也是透過那個女的才能拿到我哥的遺言。"
L15_1.m_Talk_TWN = L16_1
L16_1 = "อันที่จริง ผมก็ได้วิดีโอของเอียนมาจากเธอนั่นแหละ"
L15_1.m_Talk_THA = L16_1
L16_1 = "Thực tế là nhờ cô ấy mà tôi mới có được video của Ian."
L15_1.m_Talk_VTN = L16_1
L16_1 = "我能得到我哥的遗言，其实也是通过她。"
L15_1.m_Talk_SCN = L16_1
L16_1 = "Und tatsächlich bin ich durch sie an Ians Video gekommen."
L15_1.m_Talk_DEU = L16_1
L16_1 = "En fait, c'est grâce à elle que j'ai pu obtenir la vidéo de Ian."
L15_1.m_Talk_FRA = L16_1
L16_1 = {}
