L18_1 = "모종의 장소에서 요양 중이지."
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "某所で療養中だ。"
L17_1.m_Talk_JPN = L18_1
L18_1 = "She's recovering, in a safe place."
L17_1.m_Talk_ENG = L18_1
L18_1 = "應該正在某地療養吧。"
L17_1.m_Talk_TWN = L18_1
L18_1 = "เธอกำลังพักฟื้นในสถานที่ปลอดภัย"
L17_1.m_Talk_THA = L18_1
L18_1 = "Cô ấy đang hồi phục, ở một nơi an toàn."
L17_1.m_Talk_VTN = L18_1
L18_1 = "应该正在某地休养。"
L17_1.m_Talk_SCN = L18_1
L18_1 = "Sie erholt sich an einem sicheren Ort."
L17_1.m_Talk_DEU = L18_1
L18_1 = "Elle se rétablit, en lieu sûr."
L17_1.m_Talk_FRA = L18_1
