L19_1 = "EP5_ACT1_PROLOGUE@168#Talk"
L18_1.m_CutScenKey_Talk = L19_1
L19_1 = 168
L18_1.m_CutScenProcessKey = L19_1
L18_1.m_CutScenID = 159
L18_1.m_CutScenStrID = "EP5_ACT1_PROLOGUE"
L18_1.m_bWaitClick = true
L18_1.m_fWaitTime = 0
L18_1.m_CharStrID = "JOHN_MASON_NULL_NULL"
L18_1.m_Pos = "R"
L19_1 = "얼마 전에 놈들의 기지에 침입해서 마지막 데이터 조각을 회수하느라 심하게 다쳤거든."
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "この前、最後のデータを回収しようと奴らの基地に侵入した際に、大けがをしちまったんだ。"
L18_1.m_Talk_JPN = L19_1
L19_1 = "She recently sustained severe wounds while trying to retrieve the last piece of the data from their base."
L18_1.m_Talk_ENG = L19_1
L19_1 = "不久前，她為了去回收最後的資料部分，闖入了那些傢伙的基地並受了重傷。"
L18_1.m_Talk_TWN = L19_1
L19_1 = "เธอเพิ่งได้รับบาดเจ็บรุนแรงจากการพยายามกู้ข้อมูลชิ้นสุดท้ายจากฐานของพวกเขา"
L18_1.m_Talk_THA = L19_1
L19_1 = "Gần đây cô ấy đã chịu những vết thương nghiêm trọng trong khi cố gắng lấy lại phần dữ liệu cuối cùng từ căn cứ của chúng."
L18_1.m_Talk_VTN = L19_1
L19_1 = "不久前，她为了取回最后的数据碎片闯入了那些家伙的老巢，被伤得很重。"
L18_1.m_Talk_SCN = L19_1
L19_1 = "Sie trug unlängst schwere Verletzungen davon, als sie versuchte, den Datensatz aus der Basis zu beschaffen."
L18_1.m_Talk_DEU = L19_1
L19_1 = "Elle a été grièvement blessée en tentant de récupérer le dernier groupe de données dans leur base."
L18_1.m_Talk_FRA = L19_1
L19_1 = {}
