L21_1 = "그럼 그 데이터를 모아서 정확히 뭘 할 수 있는 거죠?"
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "では、そのデータを集めたら、実際何ができるんですか？"
L20_1.m_Talk_JPN = L21_1
L21_1 = "What exactly can we do with all the data combined?"
L20_1.m_Talk_ENG = L21_1
L21_1 = "那麼收集這些資料後，準確來說能做什麼呢？"
L20_1.m_Talk_TWN = L21_1
L21_1 = "แล้วเราจะทำอะไรกับข้อมูลทั้งหมดรวมกันได้บ้าง?"
L20_1.m_Talk_THA = L21_1
L21_1 = "Chính xác thì chúng ta có thể làm gì với tất cả dữ liệu được kết hợp?"
L20_1.m_Talk_VTN = L21_1
L21_1 = "可是汇总这些数据，能做什么呢？"
L20_1.m_Talk_SCN = L21_1
L21_1 = "Was genau könnten wir mit den kombinierten Daten anfangen?"
L20_1.m_Talk_DEU = L21_1
L21_1 = "Qu'est-ce qu'on peut faire exactement avec toutes ces données réunies ?"
L20_1.m_Talk_FRA = L21_1
