L23_1 = "리플레이서 총기함 뉴 오하이오에서 발신하는 불멸체 코어의 신호를 추적하는 법."
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "リプレイサー総旗艦のニューオハイオから送信される、不滅体コアの信号を追跡する方法。"
L22_1.m_Talk_JPN = L23_1
L23_1 = "One, the way to trace the signals of the Immortal System Core emitted from New Ohio, the flagship of the Replacer Syndicate."
L22_1.m_Talk_ENG = L23_1
L23_1 = "……一個是追蹤克隆集團總督旗艦新俄亥俄上的不滅者核心信號的方法。"
L22_1.m_Talk_TWN = L23_1
L23_1 = "หนึ่ง วิธีตามรอยสัญญาณของแกนระบบอิมมอร์ทอลที่ออกมาจากนิวโอไฮโอ ยานรบหลักของรีเพลสเซอร์ซินดิเคต"
L22_1.m_Talk_THA = L23_1
L23_1 = "Thứ nhất, cách lần theo tín hiệu của Lõi Hệ Thống Bất Diệt phát ra từ Tân Ohio, trụ sở của Nghiệp Đoàn Nhân Bản."
L22_1.m_Talk_VTN = L23_1
L23_1 = "一是可追踪克隆集团从伊欧发出的不灭者核心信号的方法。"
L22_1.m_Talk_SCN = L23_1
L23_1 = "Erstens können wir Signale des Kerns der Unsterblichkeitsmatrix aufspüren, die von der New Ohio, dem Flaggschiff des Replacer-Syndikats, ausgestrahlt werden."
L22_1.m_Talk_DEU = L23_1
L23_1 = "Premièrement, un moyen de tracer les signaux du noyau du système immortel émis par le New Ohio, le vaisseau amiral du Syndicat des substituts."
L22_1.m_Talk_FRA = L23_1
