L25_1 = "놈들이 다시 도망치지 못하도록 함선의 차원도약 기능을 일시적으로 무력화시키는 백도어 코드."
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "奴らが二度と逃げられないように、艦船の次元跳躍機能を一時的に無力化するバックドアコード。"
L24_1.m_Talk_JPN = L25_1
L25_1 = "a backdoor code that'll make them unable to flee by temporarily disabling their ship's dimension jump system."
L24_1.m_Talk_ENG = L25_1
L25_1 = "防止他們再度逃跑，可以使艦船的次元躍遷機能暫時失效的後門代碼。"
L24_1.m_Talk_TWN = L25_1
L25_1 = "รหัสประตูหลังที่จะทำให้พวกเขาไม่สามารถเผ่นหนีได้ โดยการปิดระบบจัมป์ข้ามมิติของยานชั่วคราว"
L24_1.m_Talk_THA = L25_1
L25_1 = "một mã cửa hậu sẽ khiến họ không thể chạy trốn bằng cách tạm thời vô hiệu hóa hệ thống nhảy chiều không gian của tàu của họ."
L24_1.m_Talk_VTN = L25_1
L25_1 = "以备他们逃跑，可暂时使舰船的“次元跃迁”功能失效的舱门代码。"
L24_1.m_Talk_SCN = L25_1
L25_1 = "eine Art Hintertürcode, der sie an der Flucht hindert, indem er das Dimensionssprungsystem des Schiffes vorübergehend deaktiviert."
L24_1.m_Talk_DEU = L25_1
L25_1 = "une porte dérobée dans le système qui les empêchera de fuir en bloquant temporairement la capacité de saut dimensionnel du vaisseau."
L24_1.m_Talk_FRA = L25_1
