L30_1 = "불멸체 코어의 신호 추적을 위해서는 순도 높은 대량의 이터니움 결정이 필요하거든."
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "不滅体コアの信号を追跡するためには、高純度のエタニウム結晶が大量に必要なんだ。"
L29_1.m_Talk_JPN = L30_1
L30_1 = "We need pure Eternium crystals to trace the Immortal System Core signals. A lot of them."
L29_1.m_Talk_ENG = L30_1
L30_1 = "為了追蹤不滅者核心的信號，我們需要大量的高純度永恆之金結晶。"
L29_1.m_Talk_TWN = L30_1
L30_1 = "เราต้องมีผลึกอีเทอร์เนียมบริสุทธิ์ เพื่อตามรอยสัญญาณแกนระบบอิมมอร์ทอล ต้องใช้เยอะเลย"
L29_1.m_Talk_THA = L30_1
L30_1 = "Chúng ta cần các tinh thể Vàng Vĩnh Cửu tinh khiết để theo dõi các tín hiệu của Lõi Hệ Thống Bất Diệt. Rất nhiều."
L29_1.m_Talk_VTN = L30_1
L30_1 = "为了追踪不灭者核心的信号，我们需要大量的、高纯度能晶的结晶。"
L29_1.m_Talk_SCN = L30_1
L30_1 = "Wir brauchen reine Eterniumkristalle, um die Signale des Kerns der Unsterblichkeitsmatrix aufzuspüren. Und zwar viele …"
L29_1.m_Talk_DEU = L30_1
L30_1 = "Il nous faut des cristaux d'éternium pur pour tracer les signaux du noyau du système immortel. Genre beaucoup."
L29_1.m_Talk_FRA = L30_1
