L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "並みの量でしたら、警察庁から支援を受けられると思います。"
L33_1.m_Talk_JPN = L34_1
L34_1 = "The police agency will be able to provide some for us."
L33_1.m_Talk_ENG = L34_1
L34_1 = "如果數量在合理範圍內的話，警察廳應該會給予支援的。"
L33_1.m_Talk_TWN = L34_1
L34_1 = "สำนักงานตำรวจหาให้เราได้บางส่วน"
L33_1.m_Talk_THA = L34_1
L34_1 = "Cơ quan cảnh sát sẽ có thể cung cấp một ít cho chúng tôi."
L33_1.m_Talk_VTN = L34_1
L34_1 = "如果数量在合理范围内的话，警察厅应该会给予支持的。"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Die Polizeibehörde wird uns einige zur Verfügung stellen können."
L33_1.m_Talk_DEU = L34_1
L34_1 = "L'agence de police devrait pouvoir nous en fournir."
L33_1.m_Talk_FRA = L34_1
L34_1 = {}
L35_1 = "EP5_ACT1_PROLOGUE@184#Talk"
L34_1.m_CutScenKey_Talk = L35_1
L35_1 = 184
L34_1.m_CutScenProcessKey = L35_1
L34_1.m_CutScenID = 159
L34_1.m_CutScenStrID = "EP5_ACT1_PROLOGUE"
