L34_1.m_fWaitTime = 0
L34_1.m_CharStrID = "YUMI_POLICE_NULL_NULL"
L34_1.m_Pos = "R"
L35_1 = "이런 비상사태를 위해 쓸 수 있는 긴급예산이 편성되어 있으니까요."
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "今回のような非常事態のために組まれた緊急予算がありますからね。"
L34_1.m_Talk_JPN = L35_1
L35_1 = "They have budgets spared for emergencies like this."
L34_1.m_Talk_ENG = L35_1
L35_1 = "畢竟為了應對這種緊急情況，我們會編列一定的預算。"
L34_1.m_Talk_TWN = L35_1
L35_1 = "พวกเขามีเงินสำรองสำหรับเรื่องฉุกเฉินแบบนี้"
L34_1.m_Talk_THA = L35_1
L35_1 = "Họ có ngân sách dự phòng dành cho những trường hợp khẩn cấp như thế này."
L34_1.m_Talk_VTN = L35_1
L35_1 = "对于这种紧急情况，他们有一定预算编制的。"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Für Notfälle wie diesen haben sie einen eigenen Vorrat."
L34_1.m_Talk_DEU = L35_1
L35_1 = "Ils prévoient un budget pour les urgences comme ça."
L34_1.m_Talk_FRA = L35_1
L35_1 = {}
