L41_1 = 50
L40_1.m_Crash = L41_1
L41_1 = "미, 미쳤어요?! 그건 국가예산 규모잖아요!"
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "ほ、本気ですか！？　それって国家予算並みじゃないですか！"
L40_1.m_Talk_JPN = L41_1
L41_1 = "A-are you crazy? That's almost a year's national budget!"
L40_1.m_Talk_ENG = L41_1
L41_1 = "你、你瘋了嗎？！那不是國家預算的規模嗎！"
L40_1.m_Talk_TWN = L41_1
L41_1 = "บะ-บ้าไปแล้วเหรอ? นั่นเกือบเท่ากับงบประมาณของประเทศหนึ่งปีเลยนะ!"
L40_1.m_Talk_THA = L41_1
L41_1 = "B-bạn có bị điên không? Đó là gần một năm ngân sách quốc gia!"
L40_1.m_Talk_VTN = L41_1
L41_1 = "你、你疯了吗？！那是国家预算的规制好嘛！"
L40_1.m_Talk_SCN = L41_1
L41_1 = "Sind Sie verrückt? Das ist fast der Staatshaushalt eines Jahres!"
L40_1.m_Talk_DEU = L41_1
L41_1 = "V-Vous êtes fou ? C'est pratiquement le budget national d'une année !"
L40_1.m_Talk_FRA = L41_1
L41_1 = {}
