L43_1 = "EP5_ACT1_PROLOGUE@192#Talk"
L42_1.m_CutScenKey_Talk = L43_1
L43_1 = 192
L42_1.m_CutScenProcessKey = L43_1
L42_1.m_CutScenID = 159
L42_1.m_CutScenStrID = "EP5_ACT1_PROLOGUE"
L42_1.m_bWaitClick = true
L42_1.m_fWaitTime = 0
L42_1.m_Face = "UNIT_PRIDE"
L42_1.m_CharStrID = "JOHN_MASON_NULL_NULL"
L42_1.m_Pos = "C"
L43_1 = "뭐, 평소라면 도저히 구할 수 없는 양이긴 하지."
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "まあ、通常なら到底調達できそうもない量だよな。"
L42_1.m_Talk_JPN = L43_1
L43_1 = "Well, it sure is an enormous amount."
L42_1.m_Talk_ENG = L43_1
L43_1 = "也是，這個數量一般根本無法取得。"
L42_1.m_Talk_TWN = L43_1
L43_1 = "มันก็เป็นจำนวนมหาศาลจริงนั่นละ"
L42_1.m_Talk_THA = L43_1
L43_1 = "Chà, đó chắc chắn là một con số rất lớn."
L42_1.m_Talk_VTN = L43_1
L43_1 = "也是，这个量确实很难能买到。"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Ja, es ist wirklich enorm viel."
L42_1.m_Talk_DEU = L43_1
L43_1 = "C'est sûr que c'est une énorme quantité."
L42_1.m_Talk_FRA = L43_1
L43_1 = {}
L44_1 = "EP5_ACT1_PROLOGUE@193#Talk"
L43_1.m_CutScenKey_Talk = L44_1
L44_1 = 193
L43_1.m_CutScenProcessKey = L44_1
L43_1.m_CutScenID = 159
L43_1.m_CutScenStrID = "EP5_ACT1_PROLOGUE"
L43_1.m_bWaitClick = true
L43_1.m_fWaitTime = 0
L43_1.m_CharStrID = "JOHN_MASON_NULL_NULL"
L43_1.m_Pos = "C"
L44_1 = "하지만 마침 그 정도의 이터니움을 제공해 줄 수 있는 친구들 이야기를 들었거든."
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "けど、ちょうどそれくらいのエタニウムを提供してくれる奴らの話を聞きつけたんだ。"
L43_1.m_Talk_JPN = L44_1
L44_1 = "But I hear there's a group of people who could get us that much Eternium."
L43_1.m_Talk_ENG = L44_1
L44_1 = "不過，最近我聽說有些朋友正好能提供這麼多的永恆之金。"
L43_1.m_Talk_TWN = L44_1
L44_1 = "แต่ผมได้ยินว่ามีกลุ่มคนที่สามารถหาอีเทอร์เนียมจำนวนขนาดนี้ได้"
L43_1.m_Talk_THA = L44_1
L44_1 = "Nhưng tôi nghe nói có một nhóm người có thể lấy cho chúng ta nhiều Vàng Vĩnh Cửu như vậy."
L43_1.m_Talk_VTN = L44_1
L44_1 = "但我最近知道了一些人能提供这么多量的能晶。"
L43_1.m_Talk_SCN = L44_1
L44_1 = "Aber ich habe gehört, dass es eine Gruppe von Leuten gibt, die uns so viel Eternium beschaffen können."
L43_1.m_Talk_DEU = L44_1
L44_1 = "Mais j'ai entendu dire qu'un certain groupe pourrait nous en procurer autant."
L43_1.m_Talk_FRA = L44_1
L44_1 = {}
L45_1 = "EP5_ACT1_PROLOGUE@194#Talk"
L44_1.m_CutScenKey_Talk = L45_1
L45_1 = 194
L44_1.m_CutScenProcessKey = L45_1
L44_1.m_CutScenID = 159
L44_1.m_CutScenStrID = "EP5_ACT1_PROLOGUE"
L44_1.m_bWaitClick = true
L44_1.m_fWaitTime = 0
L44_1.m_CharStrID = "JOHN_MASON_NULL_NULL"
L44_1.m_Pos = "C"
L45_1 = "그러니 일단 그 친구들을 만나 보자고."
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "だから、一応そいつらに会ってみようと思ってな。"
L44_1.m_Talk_JPN = L45_1
L45_1 = "I say we meet up with these fellas."
L44_1.m_Talk_ENG = L45_1
L45_1 = "那我們就先去見見他們吧。"
L44_1.m_Talk_TWN = L45_1
L45_1 = "ผมว่าเราควรไปพบคนพวกนี้"
L44_1.m_Talk_THA = L45_1
L45_1 = "Tôi nói chúng ta gặp những người bạn này."
L44_1.m_Talk_VTN = L45_1
L45_1 = "我们先去见见他们吧。"
L44_1.m_Talk_SCN = L45_1
L45_1 = "Ich denke, wir sollten uns mal mit diesen Leuten treffen …"
L44_1.m_Talk_DEU = L45_1
L45_1 = "Je propose d'aller leur rendre visite."
L44_1.m_Talk_FRA = L45_1
L45_1 = {}
